/* NAVO · Global HSSE Dashboard (Power BI style), built on the live NAVO data.
   Loaded after the main app script; uses its globals (L, st, render, monthCard, SHQ, ...). */
"use strict";
const HC={blue:"#118DFF",navy:"#12239E",orange:"#E66C37",purple:"#6B007B",pink:"#E044A7",green:"#1AAB40",lime:"#8BD15B",red:"#D64550",gold:"#C9A227",teal:"#0F4C5C",grey:"#B3B3B3",violet:"#9370DB"};
const HPAL=[HC.blue,HC.navy,HC.orange,HC.purple,HC.pink,HC.green,HC.gold,HC.teal,HC.red,HC.violet];
const HMON=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
const HSEC=[["exec","Executive Summary",[["sum","Executive Summary"],["close","Closure Rate"],["stats","Safety Statistics"],["waste","Waste Management"]]],
 ["health","Site Health Indicator",[["card","Site Score Card"],["actual","Actual Values"],["ind","Indicator-wise Scores"],["proj","Project Detail"]]],
 ["site","Site Dashboard",[["site","Site Dashboard"]]],
 ["inj","Injuries & Incidents",[["inj","Injuries"],["inc","Incidents"]]],
 ["aud","Audits",[["corp","Corporate Audit"],["psm","Process Safety"],["oshe","OSHE Audit"]]],
 ["acc","Accident Analysis",[["acc","Accident Analysis"],["aud","Audit Analysis"]]],
 ["kpi","Annual KPI",[["all","Corporate"],["Construction","Construction Sites"],["Non-Construction","Non-Construction Sites"]]],
 ["es","E&S Dashboard",[["griev","Grievances Management"],["accom","Worker Accommodation Assessments"]]]];
const RECORDABLE=[["Fatality","Fatality",HC.navy],["Lost Time","LTI",HC.blue],["Restricted Work","RWC",HC.pink],["Medical Treatment","MTC",HC.gold],["First Aid","FAC",HC.grey]];
const INJ_TYPES=["Cut / laceration","Bruise / contusion","Fracture","Sprain / strain","Burn","Heat stress","Eye injury","Crush","Other"];
const BODY_PARTS=["Head","Eye","Neck","Shoulder","Arm","Hand","Finger","Back","Chest","Leg","Knee","Foot","Other"];
const INC_CLASS=["Class A","Class B","Class C","Class D"];
const AUD_ELEMENTS=["Leadership & commitment","Emergency preparedness","Electrical & fire safety","Work at height","PTW / LOTO system","Lifting operations","Contractor management","Traffic management","Chemical management","PPE control","Waste & environment","Training & competence"];
const PSM_ELEMENTS=["Process safety information","Hazard identification & risk","Management of change","Mechanical integrity","Safe work practices","Incident investigation","Emergency planning","Contractor management","Training & competence","Operating procedures","Pre-startup safety review","Internal auditing"];
const GRIEV_CATS=["Salary delays / late payment","Camp conditions","Wages, hours, contracts","Staff behaviour, conflicts","HSE requirements not met","Transport","Food quality","Abusive behaviour","Pollution, noise, dust","Other"];
const ACC_CATS=["General living facilities","Canteen, cooking & laundry","Bed arrangements & storage","Sanitary & toilet facilities","Potable water","Leisure & social","Medical facilities","Fire & emergency","Welfare management"];
const NATIONS=["Indian","Pakistani","Bangladeshi","Nepali","Filipino","Egyptian","Sri Lankan","Other"];
const MF=[["Manpower",[["empHead","Employees (headcount)"],["conHead","Contractors (headcount)"],["empHours","Employee man-hours"],["conHours","Contractor man-hours"]]],
 ["Training",[["trainings","Training sessions"],["trainHours","Training man-hours"],["trainPlan","Planned training man-hours"],["attendees","Training attendees"]]],
 ["Permits & other indicators",[["ptwIssued","Permits issued"],["ptwReviewed","Permits reviewed in field"],["ptwNC","Permit non-compliances"],["ccChecks","Critical control checks"],["ccAtRisk","Critical control checks at risk"],["swa","Stop work authority used"],["drills","Emergency drills"],["committee","HSE committee meetings"],["incentives","Incentives & appreciations"],["pfpiReviewed","PFPI events reviewed by leadership"]]],
 ["Waste (tons)",[["nhDisposed","Non-hazardous disposed"],["nhRecycled","Non-hazardous recycled"],["nhReused","Non-hazardous reused"],["hzDisposed","Hazardous disposed"],["hzRecycled","Hazardous recycled"],["hzIncinerated","Hazardous incinerated"],["faDisposed","Fly ash disposed"],["faRecycled","Fly ash recycled"]]],
 ["Energy, chemicals & spills",[["diesel","Diesel (tons)"],["hfo","Heavy fuel oil (tons)"],["lpg","LPG (tons)"],["petrol","Petrol (tons)"],["gas","Natural gas (tons)"],["chemical","Chemicals (tons)"],["spill","Hazardous spillage (litres)"],["water","Water used (m³)"]]]];
const MFK=MF.flatMap(([,f])=>f.map(x=>x[0]));

/* ---------- state & scope ---------- */
function hsInit(){const d=new Date();if(!st.hs)st.hs={sec:"exec",tab:{},y:d.getFullYear(),m:0,plat:"",biz:"",proj:"",filt:false,drill:null,dt:{},sel:{}};return st.hs}
function hsP(){const h=hsInit();let P=myProjects().filter(p=>!String(p.id).startsWith("__"));if(st.country)P=P.filter(p=>p.country===st.country);
 if(h.plat)P=P.filter(p=>(p.platform||"Construction")===h.plat);if(h.biz)P=P.filter(p=>(p.division||"")===h.biz);if(h.proj)P=P.filter(p=>p.id===h.proj);return P}
const hsYM=ts=>{const d=new Date(ts);return[d.getFullYear(),d.getMonth()+1]};
function hsIn(ts){const h=hsInit();if(!ts)return false;const[y,m]=hsYM(ts);return y===h.y&&(!h.m||m===h.m)}
function hsInY(ts,y){return ts&&new Date(ts).getFullYear()===y}
const hsKey=(y,m)=>y+"-"+String(m).padStart(2,"0");
function hsMonthKey(){const h=hsInit();if(h.m)return hsKey(h.y,h.m);const d=new Date();if(h.y!==d.getFullYear())return hsKey(h.y,12);const m=d.getMonth();return m?hsKey(h.y,m):hsKey(h.y,1)}
function hsIds(P){return new Set(P.map(p=>p.id))}
function hsR(P,all){const ids=hsIds(P);return L.reports.filter(r=>ids.has(r.project)&&(all||hsIn(r.ts)))}
function hsRec(P,kind,all){const ids=hsIds(P);return(L.records||[]).filter(r=>r.kind===kind&&ids.has(r.project)&&(all||hsIn(r.ts)))}
function hsSum(rows,k){return rows.reduce((s,r)=>s+(+(r.data||{})[k]||0),0)}
function hsMon(P,all){return hsRec(P,"monthly",all)}
const hsN=v=>v==null?"—":Math.abs(v)>=1e6?(v/1e6).toFixed(2).replace(/\.?0+$/,"")+"M":Math.abs(v)>=1e4?Math.round(v).toLocaleString("en-US"):(+v).toLocaleString("en-US",{maximumFractionDigits:2});
const hsPct=(a,b)=>b?Math.round(a/b*1000)/10:null;
const sevOf=r=>r.severity||(r.kind==="First Aid"?"First Aid":"");
function incCat(r){if(r.rt!=="Incident")return null;if(r.kind==="Injury"||r.kind==="First Aid"||r.severity)return"Injury / illness";if(r.kind==="Property Damage")return"Asset damage";if(r.kind==="Environmental")return"Environmental";if(r.kind==="Fire")return"Fire";if(r.kind==="Process Safety")return"Process safety";if(r.kind==="Near Miss")return"Near miss";return"Other"}
function hsHours(P,all){const M=hsMon(P,all);return{emp:hsSum(M,"empHours"),con:hsSum(M,"conHours"),tot:hsSum(M,"empHours")+hsSum(M,"conHours")}}
function hsRate(n,hours){return hours?+(n*200000/hours).toFixed(2):0}
function hsGroup(P,by){const g={};P.forEach(p=>{const k=by==="country"?p.country:by==="platform"?(p.platform||"Construction"):by==="biz"?(p.division||"Unassigned"):p.name;(g[k]=g[k]||[]).push(p)});return g}
function hsTitle(){const h=hsInit();const P=hsP();const bits=[h.proj?projName(h.proj):h.biz||h.plat||(L.structure?.top||"Corporation")];if(st.country)bits.push(st.country);bits.push((h.m?HMON[h.m-1]+" ":"YTD ")+h.y);return bits.join(" · ")}

/* ---------- charts ---------- */
function hCard(title,body,o={}){return`<div class="hc ${o.cls||""}" ${o.style?`style="${o.style}"`:""}><div class="hc-h"><b>${title}</b>${o.right?`<span>${o.right}</span>`:""}</div><div class="hc-b">${body}</div></div>`}
function hEmpty(t){return`<p class="hs-empty">${t||"No data for this selection yet."}</p>`}
function hHbars(rows,o={}){rows=rows.filter(r=>r[1]!=null);if(!rows.length)return hEmpty();const mx=o.max||Math.max(...rows.map(r=>+r[1]||0),1);
 return`<div class="hb">${rows.map(([n,v,at,c],i)=>`<div class="hb-r ${at?"hot":""}" ${at||""}><span class="hb-l" title="${esc(n)}">${esc(n)}</span><span class="hb-t"><i style="width:${Math.max(.5,(+v||0)/mx*100)}%;background:${c||o.color||HC.blue}"></i></span><span class="hb-v">${o.fmt?o.fmt(v):hsN(v)}</span></div>`).join("")}</div>`}
function hStackH(rows,keys,cols,o={}){if(!rows.length)return hEmpty();const mx=Math.max(...rows.map(r=>r[1].reduce((a,b)=>a+b,0)),1);
 return`<div class="hb">${rows.map(([n,vs,at])=>{const t=vs.reduce((a,b)=>a+b,0);return`<div class="hb-r ${at?"hot":""}" ${at||""}><span class="hb-l">${esc(n)}</span><span class="hb-t hb-s" style="width:${Math.max(2,t/mx*100)}%">${vs.map((v,i)=>v?`<i style="flex:${v};background:${cols[i]}" title="${esc(keys[i])}: ${v}">${v/t>.12?hsN(v):""}</i>`:"").join("")}</span><span class="hb-v"><b>${hsN(t)}</b></span></div>`}).join("")}</div>${o.legend!==false?hLeg(keys,cols):""}`}
function hLeg(keys,cols){return`<div class="hleg">${keys.map((k,i)=>`<span><i style="background:${cols[i]}"></i>${esc(k)}</span>`).join("")}</div>`}
function hVbars(cats,series,o={}){const n=cats.length;if(!n||!series.length)return hEmpty();const h=o.h||150,W=Math.max(300,n*(o.bw||(series.length>1&&!o.stack?64:46))),pad=22;
 const tot=i=>o.stack?series.reduce((s,se)=>s+(+se.v[i]||0),0):Math.max(...series.map(se=>+se.v[i]||0));const mx=Math.max(1,...cats.map((_,i)=>tot(i)),o.target||0)*1.18;
 const bw=W/n,y=v=>pad+h-(v/mx)*h;let g="";const rot=cats.some(c=>String(c).length>Math.floor(bw/6.4));const bot=rot?58:22;
 cats.forEach((c,i)=>{const at=o.attr?o.attr(i):"";let acc=0;const inner=o.stack?bw*.62:bw*.74/series.length;
  series.forEach((se,si)=>{const v=+se.v[i]||0;if(!v&&!o.stack)return;const x=o.stack?i*bw+bw*.19:i*bw+bw*.13+si*inner;const top=o.stack?y(acc+v):y(v);const hh=o.stack?y(acc)-y(acc+v):pad+h-y(v);
   g+=`<rect x="${x}" y="${top}" width="${inner-2}" height="${Math.max(0,hh)}" fill="${se.c}" rx="1" ${at} ${at?'class="hot"':""}><title>${esc(c)} · ${esc(se.n)}: ${hsN(v)}</title></rect>`;
   if(!o.stack&&o.vals!==false)g+=`<text x="${x+(inner-2)/2}" y="${top-4}" text-anchor="middle" class="hv">${hsN(v)}</text>`;
   else if(o.stack&&hh>13&&o.vals!==false)g+=`<text x="${x+(inner-2)/2}" y="${top+hh/2+4}" text-anchor="middle" class="hv w">${hsN(v)}</text>`;acc+=v});
  if(o.stack&&o.vals!==false)g+=`<text x="${i*bw+bw/2}" y="${y(acc)-4}" text-anchor="middle" class="hv b">${hsN(acc)}</text>`;
  const lb=String(c);g+=rot?`<text x="${i*bw+bw/2+4}" y="${pad+h+12}" text-anchor="end" class="hx" transform="rotate(-35 ${i*bw+bw/2+4} ${pad+h+12})">${esc(lb.length>18?lb.slice(0,17)+"…":lb)}<title>${esc(lb)}</title></text>`:`<text x="${i*bw+bw/2}" y="${pad+h+14}" text-anchor="middle" class="hx">${esc(lb)}</text>`});
 if(o.target)g+=`<line x1="0" x2="${W}" y1="${y(o.target)}" y2="${y(o.target)}" stroke="${HC.red}" stroke-dasharray="5 4"/>`;
 if(o.rate){const pts=o.rate.map((r,i)=>r==null?null:[i*bw+bw/2,pad+(1-r/100)*h]);const ok=pts.filter(Boolean);
  g+=`<polyline fill="none" stroke="${HC.gold}" stroke-width="2" points="${ok.map(p=>p.join(",")).join(" ")}"/>`+pts.map((p,i)=>p?`<circle cx="${p[0]}" cy="${p[1]}" r="3" fill="${HC.gold}"/><text x="${p[0]}" y="${p[1]-6}" text-anchor="middle" class="hv g">${o.rate[i]}%</text>`:"").join("")}
 const lx=rot?44:0;return`<div class="hsvg"><svg viewBox="${-lx} 0 ${W+lx} ${pad+h+bot}" style="max-height:${Math.round((pad+h+bot)*1.45)}px">${g}</svg></div>${o.legend?hLeg(series.map(s=>s.n).concat(o.rate?["Closure rate"]:[]),series.map(s=>s.c).concat(o.rate?[HC.gold]:[])):""}`}
function hLine(cats,series,o={}){const n=cats.length;if(!n)return hEmpty();const h=o.h||140,W=Math.max(320,n*42),pad=18;const all=series.flatMap(s=>s.v).filter(v=>v!=null).concat(o.band?o.band[1]:0,o.max||0);
 const mx=o.max||(Math.max(...all,0.01)*1.2);const x=i=>18+i*(W-36)/Math.max(1,n-1),y=v=>pad+h-(v/mx)*h;let g="";
 if(o.band)g+=`<rect x="0" y="${y(o.band[1])}" width="${W}" height="${y(o.band[0])-y(o.band[1])}" fill="#7fd1a8" opacity=".45"/>`;
 [0,.5,1].forEach(f=>g+=`<line x1="0" x2="${W}" y1="${y(mx*f/1.2)}" y2="${y(mx*f/1.2)}" stroke="var(--line)" stroke-dasharray="2 3"/>`);
 series.forEach(s=>{const pts=s.v.map((v,i)=>v==null?null:[x(i),y(v)]).filter(Boolean);if(!pts.length)return;
  if(o.area)g+=`<polygon fill="${s.c}" opacity=".35" points="${pts[0][0]},${pad+h} ${pts.map(p=>p.join(",")).join(" ")} ${pts[pts.length-1][0]},${pad+h}"/>`;
  g+=`<polyline fill="none" stroke="${s.c}" stroke-width="2.2" ${s.dash?'stroke-dasharray="5 4"':""} points="${pts.map(p=>p.join(",")).join(" ")}"/>`;
  s.v.forEach((v,i)=>{if(v==null)return;g+=`<circle cx="${x(i)}" cy="${y(v)}" r="3" fill="${s.c}"><title>${esc(s.n)} · ${esc(cats[i])}: ${hsN(v)}${o.unit||""}</title></circle>`;if(o.vals)g+=`<text x="${x(i)}" y="${y(v)-7}" text-anchor="middle" class="hv">${hsN(v)}${o.unit||""}</text>`})});
 cats.forEach((c,i)=>{if(n>14&&i%2)return;g+=`<text x="${x(i)}" y="${pad+h+14}" text-anchor="middle" class="hx">${esc(c)}</text>`});
 return`<div class="hsvg"><svg viewBox="0 0 ${W} ${pad+h+20}" style="max-height:${Math.round((pad+h+20)*1.6)}px">${g}</svg></div>${series.length>1||o.legend?hLeg(series.map(s=>s.n),series.map(s=>s.c)):""}`}
function hGauge(v,t,mx,label){const r=60,cx=80,cy=74,a=f=>Math.PI*(1-Math.min(1,Math.max(0,f)));const pt=(f,rr)=>[cx+rr*Math.cos(a(f)),cy-rr*Math.sin(a(f))];
 const arc=(f0,f1,c,w)=>{const[x0,y0]=pt(f0,r),[x1,y1]=pt(f1,r);return`<path d="M${x0},${y0}A${r},${r} 0 0 1 ${x1},${y1}" stroke="${c}" stroke-width="${w}" fill="none"/>`};
 const f=mx?v/mx:0,ft=mx?t/mx:0;const[tx0,ty0]=pt(ft,r-14),[tx1,ty1]=pt(ft,r+12);const bad=v>t;
 return`<svg viewBox="0 0 160 100" class="hg">${arc(0,1,"#e9e9e9",18)}${f>0?arc(0,f,bad?HC.red:HC.blue,18):""}<line x1="${tx0}" y1="${ty0}" x2="${tx1}" y2="${ty1}" stroke="${HC.red}" stroke-width="2.5"/><text x="80" y="70" text-anchor="middle" font-size="20" fill="${bad?HC.red:HC.blue}">${(+v).toFixed(2)}</text><text x="80" y="86" text-anchor="middle" font-size="9" fill="var(--muted)">${label||"Actual"} · target ${t}</text><text x="18" y="96" font-size="9" fill="var(--muted)">0</text><text x="142" y="96" text-anchor="end" font-size="9" fill="var(--muted)">${mx}</text></svg>`}
function hTreemap(items){items=items.map(i=>[i[0],i[1],i[2],i[3]||""]).filter(i=>i[1]>0).sort((a,b)=>b[1]-a[1]);if(!items.length)return hEmpty();const out=[];
 const lay=(its,x,y,w,h)=>{if(!its.length)return;if(its.length===1){out.push([...its[0],x,y,w,h]);return}const tot=its.reduce((s,i)=>s+i[1],0);let acc=0,k=0;while(k<its.length-1&&acc+its[k][1]<tot/2){acc+=its[k][1];k++}if(k===0){acc=its[0][1];k=1}
  const f=acc/tot;if(w>=h){lay(its.slice(0,k),x,y,w*f,h);lay(its.slice(k),x+w*f,y,w*(1-f),h)}else{lay(its.slice(0,k),x,y,w,h*f);lay(its.slice(k),x,y+h*f,w,h*(1-f))}};
 lay(items,0,0,100,100);return`<div class="htm">${out.map(([n,v,c,at,x,y,w,h])=>`<div ${at||""} class="${at?"hot":""}" style="left:${x}%;top:${y}%;width:${w}%;height:${h}%;background:${c}" title="${esc(n)}: ${v}"><span>${esc(n)}</span><b>${hsN(v)}</b></div>`).join("")}</div>`}
function hKpi(label,val,o={}){return`<div class="hk ${o.cls||""}" ${o.attr||""}><small>${label}</small><b style="${o.color?`color:${o.color}`:""}">${val}</b>${o.sub?`<em>${o.sub}</em>`:""}</div>`}
function hDonut(parts,center,sub,attr){return parts.some(p=>p[1])?donut(parts,center,sub,attr):hEmpty()}
function hTable(head,rows,o={}){if(!rows.length)return hEmpty(o.empty);return`<div class="tbl hs-tbl" ${o.h?`style="max-height:${o.h}px;overflow:auto"`:""}><table><thead><tr>${head.map(x=>`<th ${/^[#%]|Score|Actual|Target|Max|Workers|Camps|Injuries|Count|Rate|Hours|Days/.test(x)?'class="r"':""}>${x}</th>`).join("")}</tr></thead><tbody>${rows.join("")}</tbody></table></div>`}
const hAt=(k,v)=>`data-hx="${esc(k)}" data-hv="${esc(v)}"`;

/* ---------- shared pieces ---------- */
function hsDiamond(P){const R=hsR(P),A=L.actions.filter(a=>hsIds(P).has(a.project)&&hsIn(a.ts)),I=L.inspections.filter(i=>hsIds(P).has(i.project)&&hsIn(i.ts)),V=L.activities.filter(v=>hsIds(P).has(v.project)&&hsIn(v.date)),M=hsMon(P),F=hsRec(P,"finding");
 const sev=s=>R.filter(r=>sevOf(r)===s).length,k=x=>R.filter(r=>incCat(r)===x).length,cnt=t=>V.filter(v=>v.type===t).reduce((s,v)=>s+(+v.count||1),0);
 const items=[["Fatalities",sev("Fatality"),"sev:Fatality"],["Lost time injuries",sev("Lost Time"),"sev:Lost Time"],["Restricted work cases",sev("Restricted Work"),"sev:Restricted Work"],["Medical treatment",sev("Medical Treatment"),"sev:Medical Treatment"],["First aid cases",sev("First Aid"),"sev:First Aid"],["Asset damage",k("Asset damage"),"inc:Asset damage"],["Fire incidents",k("Fire"),"inc:Fire"],["Process safety",k("Process safety"),"inc:Process safety"],["Environmental",k("Environmental"),"inc:Environmental"],
  ["Near misses",R.filter(r=>r.kind==="Near Miss").length,"nearmiss"],["Unsafe acts / cond.",R.filter(r=>r.rt==="Hazard").length,"hazards"],["HSE audit findings",F.length,"audits"],["HSE trainings",hsSum(M,"trainings"),""],["Training man-hours",hsSum(M,"trainHours"),""],["HSE inspections",I.length,"insp"],["Leadership walks",cnt("Leadership walkthrough"),"walks"],["Permit reviews",hsSum(M,"ptwReviewed"),""],["Stop work authority",hsSum(M,"swa"),""],["Toolbox talks",cnt("Toolbox talk"),"tbt"],["Emergency drills",hsSum(M,"drills"),""]];
 return pyramid(items.map(([n,v,d])=>[n,v,d?"h:"+d:""]),9)}
function hsCountryCombo(P,rowsFn,closedFn){const g=hsGroup(P,"country");const cats=Object.keys(g).sort();const raised=cats.map(c=>rowsFn(g[c]).length),closed=cats.map(c=>rowsFn(g[c]).filter(closedFn).length);
 const tr=raised.reduce((a,b)=>a+b,0),tc=closed.reduce((a,b)=>a+b,0);return{body:hVbars(cats,[{n:"Raised",v:raised,c:HC.blue},{n:"Closed",v:closed,c:HC.lime}],{rate:raised.map((r,i)=>r?Math.round(closed[i]/r*1000)/10:null),legend:true,attr:i=>hAt("country",cats[i])}),right:`Raised <b>${hsN(tr)}</b> · Closed <b>${hsN(tc)}</b> · Rate <b>${tr?(tc/tr*100).toFixed(2):"—"}%</b>`}}
function hsMonthly(P,fn,y){y=y||hsInit().y;return HMON.map((_,i)=>fn(i+1,y))}

/* ---------- 1. Executive summary ---------- */
function hsExecSum(P){const M=hsMon(P),R=hsR(P);const byPlat=hsGroup(P,"platform"),plats=Object.keys(byPlat);
 const manpower=hTable(["Platform","Employees","Contractors"],plats.map(pl=>{const m=hsMon(byPlat[pl]);const last=hsLatest(m);return`<tr class="hot" ${hAt("plat",pl)}><td>${esc(pl)}</td><td class="r">${hsN(hsSum(last,"empHead"))}</td><td class="r">${hsN(hsSum(last,"conHead"))}</td></tr>`}).concat([`<tr class="tot"><td>Total</td><td class="r">${hsN(hsSum(hsLatest(M),"empHead"))}</td><td class="r">${hsN(hsSum(hsLatest(M),"conHead"))}</td></tr>`]));
 const hours=hTable(["Platform","Employees","Contractors"],plats.map(pl=>{const m=hsMon(byPlat[pl]);return`<tr class="hot" ${hAt("plat",pl)}><td>${esc(pl)}</td><td class="r">${hsN(hsSum(m,"empHours"))}</td><td class="r">${hsN(hsSum(m,"conHours"))}</td></tr>`}).concat([`<tr class="tot"><td>Total</td><td class="r">${hsN(hsSum(M,"empHours"))}</td><td class="r">${hsN(hsSum(M,"conHours"))}</td></tr>`]));
 const safe=(grp,key)=>hTable([key==="plat"?"Platform":"Country","Safe work hours","Safe days"],Object.entries(grp).map(([k,ps])=>{const s=hsSafe(ps);return`<tr class="hot" ${hAt(key,k)}><td>${esc(k)}</td><td class="r">${hsN(s.hours)}</td><td class="r">${s.days}</td></tr>`}));
 const rec=RECORDABLE.slice(0,4).map(([s,n,c])=>[n,R.filter(r=>sevOf(r)===s).length,c]);const recTot=rec.reduce((a,b)=>a+b[1],0);
 const byC=hsGroup(P,"country");const reg=hStackH(Object.entries(byC).sort((a,b)=>hsHours(b[1]).tot-hsHours(a[1]).tot).map(([c,ps])=>[c,[hsHours(ps).emp,hsHours(ps).con],hAt("country",c)]),["Employee hours","Contractor hours"],[HC.purple,HC.navy]);
 const cy=hsInit().y;const yrs=[...new Set(hsMon(P,true).map(m=>new Date(m.ts).getFullYear()))].filter(y=>y<=cy).sort();const all=hsR(P,true),Mall=hsMon(P,true);
 const yrRate=(y,sevs)=>{const n=all.filter(r=>hsInY(r.ts,y)&&sevs.includes(sevOf(r))).length;const hrs=Mall.filter(m=>hsInY(m.ts,y)).reduce((s,m)=>s+(+m.data.empHours||0)+(+m.data.conHours||0),0);return hrs?hsRate(n,hrs):null};
 const tg=hsTargets();
 const trends=`<div class="hs-2">${hCard("LTIR",hLine(yrs.map(String),[{n:"Actual rate",v:yrs.map(y=>yrRate(y,["Lost Time","Fatality"])),c:HC.orange},{n:"Target rate",v:yrs.map(()=>tg.ltir),c:HC.red,dash:1}],{vals:1,h:110}),{cls:"flat"})}${hCard("TRIR",hLine(yrs.map(String),[{n:"Actual rate",v:yrs.map(y=>yrRate(y,["Lost Time","Fatality","Restricted Work","Medical Treatment"])),c:HC.navy},{n:"Target rate",v:yrs.map(()=>tg.trir),c:HC.blue,dash:1}],{vals:1,h:110}),{cls:"flat"})}</div>`;
 return`<div class="hs-g4">${hCard("Manpower",manpower,{cls:"b-red"})}${hCard("Hours worked",hours,{cls:"b-blue"})}${hCard("Safe work hours",safe(byPlat,"plat"),{cls:"b-gold"})}${hCard("Geo-wise",safe(byC,"country"),{cls:"b-gold"})}</div>
 <div class="hs-main"><div>${`<div class="hs-2">${hCard("Recordable cases",hDonut(rec,recTot,"cases",n=>hAt("h","sev:"+RECORDABLE.find(r=>r[1]===n)[0])))}${hCard("Region-wise work hours",reg)}</div>`}${hCard("HSE lagging indicator trends",trends,{right:"per 200,000 man-hours"})}</div>${hCard("Lagging & leading indicators",hsDiamond(P),{cls:"tall"})}</div>`}
function hsLatest(M){const by={};M.forEach(m=>{const k=m.project;if(!by[k]||m.ts>by[k].ts)by[k]=m});return Object.values(by)}
function hsSafe(P){const ids=hsIds(P);const lti=L.reports.filter(r=>ids.has(r.project)&&["Lost Time","Fatality"].includes(sevOf(r))).sort((a,b)=>b.ts-a.ts)[0];const since=lti?lti.ts:0;
 const hours=hsMon(P,true).filter(m=>m.ts>=since).reduce((s,m)=>s+(+m.data.empHours||0)+(+m.data.conHours||0),0);const first=Math.min(...hsMon(P,true).map(m=>m.ts),Date.now());
 return{hours,days:Math.floor((Date.now()-(lti?lti.ts:first))/864e5),last:lti}}
function hsTargets(){const t=(L.structure&&L.structure.targets)||{};return{ltir:+t.ltir||0.1,trir:+t.trir||0.4,psm:+t.psm||4,audit:+t.audit||80}}
function hsClosure(P){const ids=hsIds(P);const R=hsR(P);const A=L.actions.filter(a=>ids.has(a.project)&&hsIn(a.ts));const F=hsRec(P,"finding");const G=hsRec(P,"grievance");
 const c=(t,fn,cl)=>{const x=hsCountryCombo(P,fn,cl);return hCard(t,x.body,{right:x.right})};
 return`<div class="hs-2">${c("NAVO cases (all reports)",ps=>hsR(ps),r=>r.status==="Closed")}${c("NAVO actions",ps=>{const s=hsIds(ps);return A.filter(a=>s.has(a.project))},a=>!!a.closedAt)}
 ${c("Audit findings",ps=>{const s=hsIds(ps);return F.filter(f=>s.has(f.project))},f=>f.data.status==="Closed")}${c("Observations (unsafe acts & conditions)",ps=>hsR(ps).filter(r=>r.rt==="Hazard"),r=>r.status==="Closed")}
 ${c("Incidents & lessons learnt",ps=>hsR(ps).filter(r=>r.rt==="Incident"),r=>r.status==="Closed")}${c("Grievances",ps=>{const s=hsIds(ps);return G.filter(f=>s.has(f.project))},g=>g.data.status==="Closed")}</div>`}
function hsStats(P){const h=hsInit();const M=hsMon(P),F=hsRec(P,"finding"),byC=hsGroup(P,"country"),cs=Object.keys(byC).sort();const ids=hsIds(P);
 const aud=["Corporate","Process Safety","OSHE"].map(a=>[a+" audits",cs.map(c=>F.filter(f=>f.data.audit===a&&byC[c].some(p=>p.id===f.project)).length)]);
 const inspBy=cs.map(c=>L.inspections.filter(i=>hsIn(i.ts)&&byC[c].some(p=>p.id===i.project)).length);
 const sel=h.sel.trend||"Observations";const series={"Leadership walkthroughs":(mo,y)=>L.activities.filter(v=>ids.has(v.project)&&v.type==="Leadership walkthrough"&&hsYM(v.date)[0]===y&&hsYM(v.date)[1]===mo).reduce((s,v)=>s+(+v.count||1),0),
  Observations:(mo,y)=>L.reports.filter(r=>ids.has(r.project)&&r.rt==="Hazard"&&hsYM(r.ts)[0]===y&&hsYM(r.ts)[1]===mo).length,"Permit reviews":(mo,y)=>hsSum(hsMon(P,true).filter(m=>m.data.month===hsKey(y,mo)),"ptwReviewed"),
  Inspections:(mo,y)=>L.inspections.filter(i=>ids.has(i.project)&&hsYM(i.ts)[0]===y&&hsYM(i.ts)[1]===mo).length};
 const other=[["SWA","swa"],["Incentives & appreciations","incentives"],["Drills","drills"],["Committee meetings","committee"]];
 return`<div class="hs-3">${hCard("Audits",hStackH(aud.map(([n])=>[n,cs.map((c,i)=>aud.find(a=>a[0]===n)[1][i])]),cs,HPAL),{right:hsN(F.length)})}
  ${hCard("Trainings",hHbars(cs.map((c,i)=>[c,hsSum(hsMon(byC[c]),"trainings"),hAt("country",c),HPAL[i]])),{right:hsN(hsSum(M,"trainings"))})}
  ${hCard("Training man-hours",hVbars(cs,[{n:"Man-hours",v:cs.map(c=>hsSum(hsMon(byC[c]),"trainHours")),c:HC.navy}],{attr:i=>hAt("country",cs[i]),h:110}),{right:hsN(hsSum(M,"trainHours"))})}
  ${hCard("Permit reviews",hDonut(cs.map((c,i)=>[c,hsSum(hsMon(byC[c]),"ptwReviewed"),HPAL[i]]),hsN(hsSum(M,"ptwReviewed")),"reviews",n=>hAt("country",n.replace(/ [\d,.KM]+$/,""))))}
  ${hCard("Permit non-compliance",hDonut(cs.map((c,i)=>[c,hsSum(hsMon(byC[c]),"ptwNC"),HPAL[i]]),hsN(hsSum(M,"ptwNC")),"NC"))}
  ${hCard("Training attendees",hLine(cs,[{n:"Attendees",v:cs.map(c=>hsSum(hsMon(byC[c]),"attendees")),c:HC.blue}],{area:1,vals:1,h:110}),{right:hsN(hsSum(M,"attendees"))})}
  ${hCard("Inspections",hStackH([["Inspections",inspBy]],cs,HPAL),{right:hsN(inspBy.reduce((a,b)=>a+b,0))})}
  ${hCard("Other indicators",hVbars(other.map(o=>o[0]),cs.map((c,i)=>({n:c,v:other.map(o=>hsSum(hsMon(byC[c]),o[1])),c:HPAL[i]})),{stack:1,legend:1,h:130}))}
  ${hCard("Monthly trends",`<div class="hseg">${Object.keys(series).map(k=>`<button data-hsel="trend" data-v="${esc(k)}" aria-pressed="${k===sel}">${k}</button>`).join("")}</div>`+hLine(HMON,[{n:sel,v:hsMonthly(P,series[sel]),c:HC.blue}],{area:1,vals:1,h:120}))}</div>`}
function hsWaste(P){const M=hsMon(P),h=hsInit();const s=k=>hsSum(M,k);const sel=h.sel.waste||"Hazardous";
 const tk={"Non-hazardous":["nhDisposed","nhRecycled","nhReused"],"Hazardous":["hzDisposed","hzRecycled","hzIncinerated"],"Fly ash":["faDisposed","faRecycled"]}[sel];
 const bySite=P.map(p=>[p.name,tk.map(k=>hsSum(M.filter(m=>m.project===p.id),k)),hAt("proj",p.id)]).filter(r=>r[1].some(Boolean)).sort((a,b)=>b[1].reduce((x,y)=>x+y,0)-a[1].reduce((x,y)=>x+y,0));
 const fuel=[["Diesel","diesel",HC.blue],["Heavy fuel oil","hfo",HC.navy],["LPG","lpg",HC.orange],["Petrol","petrol",HC.purple]].map(([n,k,c])=>[n,s(k),c]);
 const trend=HMON.map((_,i)=>{const mm=M.filter(m=>m.data.month===hsKey(h.y,i+1));return["hzDisposed","hzRecycled","hzIncinerated"].reduce((t,k)=>t+hsSum(mm,k),0)});
 return`<div class="hs-waste"><div class="hs-3">${hCard("Non-hazardous waste",hVbars(["Disposed","Recycled","Reused"],[{n:"tons",v:[s("nhDisposed"),s("nhRecycled"),s("nhReused")],c:"#3B5B85"}],{h:100}))}${hCard("Hazardous waste",hVbars(["Disposed","Recycled","Incinerated"],[{n:"tons",v:[s("hzDisposed"),s("hzRecycled"),s("hzIncinerated")],c:"#3B5B85"}],{h:100}))}${hCard("Fly ash",hVbars(["Disposed","Recycled"],[{n:"tons",v:[s("faDisposed"),s("faRecycled")],c:"#3B5B85"}],{h:100}))}</div>
 <div class="hs-wmid"><div>${hCard("Hazardous spillage (litres)",`<div class="hbig">${hsN(s("spill"))}</div>`)}${hCard("Chemical consumption (tons)",`<div class="hbig">${hsN(s("chemical"))}</div>`)}${hCard("Natural gas consumption (tons)",`<div class="hbig">${hsN(s("gas"))}</div>`)}</div>${hCard("Fuel consumption (tons)",hDonut(fuel,hsN(fuel.reduce((a,b)=>a+b[1],0)),"tons"))}</div>
 ${hCard("Monthly trend for hazardous waste (tons)",hVbars(HMON,[{n:"tons",v:trend,c:HC.gold}],{h:90}))}</div>
 ${hCard("Waste treatment (tons)",`<div class="hseg">${["Non-hazardous","Hazardous","Fly ash"].map(k=>`<button data-hsel="waste" data-v="${k}" aria-pressed="${k===sel}">${k}</button>`).join("")}</div>`+hStackH(bySite.slice(0,25),sel==="Fly ash"?["Disposed","Recycled"]:sel==="Hazardous"?["Disposed","Recycled","Incinerated"]:["Disposed","Recycled","Reused"],["#3B5B85",HC.green,HC.gold]),{cls:"tall"})}</div>`}

/* ---------- 2. Site health indicator ---------- */
function hsCards(P){const m=hsMonthKey();const[y,mo]=m.split("-").map(Number);const pm=mo===1?hsKey(y-1,12):hsKey(y,mo-1);
 return P.map(p=>{const c=monthCard(p.id,m),pc=monthCard(p.id,pm);const has=L.reports.some(r=>r.project===p.id&&inMonth(r.ts,m))||L.inspections.some(i=>i.project===p.id&&inMonth(i.ts,m));
  return{p,c,score:has?c.total:null,prev:has?pc.total:null,status:has?statusFor(c.total,pc.total):null}}).sort((a,b)=>(b.score??-1)-(a.score??-1))}
const HSTAT={Improving:["✔",HC.green],Monitor:["▲","#E6B800"],Review:["!","#E08A00"],Intervention:["✖",HC.red]};
function hsBand(s){return s==null?"#ddd":s>=80?HC.green:s>=60?"#F2D600":s>=40?"#F2A900":HC.red}
function hsHealthCard(P){const C=hsCards(P);const h=hsInit();const cnt=s=>C.filter(x=>x.status===s).length;
 const ind=h.sel.ind||"1_1";const[si,ii]=ind.split("_").map(Number);const indName=SHQ[si][1][ii][0];
 const flagged=SHQ.flatMap(([sec,inds],a)=>inds.map(([n],b)=>[n,C.filter(x=>x.c.rows[a].ir[b].a!=null&&!x.c.rows[a].ir[b].ok).length])).filter(x=>x[1]).sort((a,b)=>b[1]-a[1]);
 const bands=[["80 – 100",C.filter(x=>x.score>=80).length,HC.green],["60 – 79",C.filter(x=>x.score>=60&&x.score<80).length,"#F2D600"],["40 – 59",C.filter(x=>x.score>=40&&x.score<60).length,"#F2A900"],["< 40",C.filter(x=>x.score!=null&&x.score<40).length,HC.red]];
 return`<div class="hs-health"><div>${hCard("Site score card · "+HMON[+hsMonthKey().slice(5)-1]+" "+hsMonthKey().slice(0,4),hTable(["Site","Quantitative score","Qualitative score","Overall score","System health"],C.map(x=>`<tr class="hot" ${hAt("proj",x.p.id)}><td>${esc(x.p.name)}</td><td class="r">${x.score==null?"—":x.c.quant.toFixed(2)}</td><td class="r">${x.score==null?"—":x.c.hasQual?x.c.qual.toFixed(2):"<small>not reviewed</small>"}</td><td class="r hsc" style="background:${hsBand(x.score)}">${x.score==null?"—":x.score.toFixed(2)}</td><td>${x.status?`<span style="color:${HSTAT[x.status][1]}">${HSTAT[x.status][0]}</span> ${x.status}`:"No data"}</td></tr>`),{h:520}),{cls:"tall"})}</div>
 <div><div class="hs-2">${hCard("HSSE system health",`<div class="hsys">${Object.entries(HSTAT).map(([k,[i,c]])=>`<div><small>${k}</small><b><span style="color:${c}">${i}</span> ${cnt(k)}</b></div>`).join("")}</div>`)}${hCard("Site health indicator",hsColBars(bands.map(b=>[b[0],b[1],b[2]])))}</div>
 <div class="hs-2">${hCard("HSSE critical indicators",`<select class="hs-in" data-hsel="ind">${SHQ.flatMap(([s,inds],a)=>inds.map(([n],b)=>`<option value="${a}_${b}" ${ind===a+"_"+b?"selected":""}>${esc(n)}</option>`)).join("")}</select>`+hHbars(C.filter(x=>x.c.rows[si].ir[ii].a!=null).sort((a,b)=>b.c.rows[si].ir[ii].a-a.c.rows[si].ir[ii].a).map(x=>[x.p.name,x.c.rows[si].ir[ii].a,hAt("proj",x.p.id),x.c.rows[si].ir[ii].ok?"#A9D3FF":HC.red])))}${hCard("Number of sites red-flagged per indicator",hHbars(flagged.map(([n,v])=>[n,v,"",HC.teal])))}</div></div></div>`}
function hsMatrix(P,mode){const C=hsCards(P).filter(x=>x.score!=null);if(!C.length)return hCard(mode==="actual"?"Actual values":"Indicator-wise scores",hEmpty());
 const head=["Indicator",...C.map(x=>`<span class="hot" ${hAt("proj",x.p.id)}>${esc(x.p.name)}</span>`)];
 const rows=[`<tr class="sec"><td>Quantitative score</td>${C.map(x=>`<td class="r">${x.c.quant.toFixed(2)}</td>`).join("")}</tr>`];
 SHQ.forEach(([sec,inds],a)=>{rows.push(`<tr class="sec"><td>${esc(sec)}</td>${C.map(x=>`<td class="r">${x.c.rows[a].st.toFixed(2)}</td>`).join("")}</tr>`);
  inds.forEach(([n,u],b)=>rows.push(`<tr><td>${esc(n)}</td>${C.map(x=>{const i=x.c.rows[a].ir[b];return`<td class="r ${i.a!=null&&!i.ok?"bad":""}">${mode==="actual"?(i.a==null?"—":hsN(i.a)+(u==="%"?"%":"")):i.sc.toFixed(2)}</td>`}).join("")}</tr>`))});
 return hCard(mode==="actual"?"Actual values · "+hsMonthKey():"Indicator-wise scores · "+hsMonthKey(),`<div class="tbl hs-tbl hs-mx" style="max-height:620px;overflow:auto"><table><thead><tr>${head.map(x=>`<th>${x}</th>`).join("")}</tr></thead><tbody>${rows.join("")}</tbody></table></div>`)}
function hsProjDetail(P){const h=hsInit();const pid=h.proj||h.sel.proj||(P[0]&&P[0].id);if(!pid)return hCard("Project detail",hEmpty("No projects."));const p=L.projects.find(x=>x.id===pid);const m=hsMonthKey();const c=monthCard(pid,m);
 const q=c.rows.flatMap((r,a)=>[`<tr class="sec"><td>${esc(r.sec)}</td><td></td><td></td><td class="r">${r.max.toFixed(2)}</td><td class="r">${r.st.toFixed(2)}</td></tr>`,...r.ir.map(i=>`<tr><td>${esc(i.n)}</td><td class="r ${i.a!=null&&!i.ok?"bad":""}">${i.a==null?"—":hsN(i.a)+(i.u==="%"?"%":"")}${i.a!=null&&!i.ok?" ⚑":""}</td><td class="r">${i.u==="#"||i.u==="/100"?"":""}${(SHQ[a][1].find(x=>x[0]===i.n)[4]?"≥ ":"≤ ")+i.t}${i.u==="%"?"%":""}</td><td class="r">${i.mx.toFixed(2)}</td><td class="r">${i.sc.toFixed(2)}</td></tr>`)]);
 const ql=c.ql.map(x=>`<tr><td>${esc(x.n)}</td><td class="r">${c.hasQual?x.r+" / 5":"—"}</td><td class="r">${x.mx.toFixed(2)}</td><td class="r">${c.hasQual?x.sc.toFixed(2):"—"}</td></tr>`);
 const trend=[];const[y]=m.split("-").map(Number);for(let i=1;i<=12;i++){const k=hsKey(y,i);trend.push(L.reports.some(r=>r.project===pid&&inMonth(r.ts,k))?monthCard(pid,k).total:null)}
 return`<div class="hs-proj-h"><select class="hs-in" data-hsel="proj">${P.map(x=>`<option value="${x.id}" ${x.id===pid?"selected":""}>${esc(x.name)}</option>`).join("")}</select><span>Overall score <b style="color:${hsBand(c.total)}">${c.total.toFixed(2)}</b></span></div>
 <div class="hs-2">${hCard("Quantitative score",hTable(["Indicator","Actual","Target","Max","Score"],q),{right:"Total "+c.quant.toFixed(2)})}<div>${hCard("Qualitative score",hTable(["Indicator","Rating","Max","Score"],ql),{right:c.hasQual?"Total "+c.qual.toFixed(2):"Not reviewed yet"})}${hCard("Monthly trend",hLine(HMON,[{n:"Score",v:trend,c:HC.orange}],{vals:1,max:100,h:110}))}${hCard("Improvement plan",`<p style="margin:0;white-space:pre-wrap">${esc(c.rv.note||"No improvement plan recorded. Add one on Admin review.")}</p>`)}</div></div>`}

