function hsSite(P){const h=hsInit();const byC=hsGroup(myProjects(),"country");const cs=Object.keys(byC).sort();const R=hsR(P),M=hsMon(P),last=hsLatest(M);
 const hrs=hsHours(P);const sev=s=>R.filter(r=>sevOf(r)===s).length;const lti=sev("Lost Time")+sev("Fatality"),rec=lti+sev("Restricted Work")+sev("Medical Treatment");const sf=hsSafe(P);
 const A=hsRec(P,"audit").filter(a=>a.data.audit!=="Process Safety").sort((a,b)=>b.ts-a.ts)[0];const psm=hsRec(P,"audit").filter(a=>a.data.audit==="Process Safety").sort((a,b)=>b.ts-a.ts)[0];
 const ids=hsIds(P);const Ac=L.actions.filter(a=>ids.has(a.project)&&hsIn(a.ts));const F=hsRec(P,"finding");
 const cl=[["Observations",R.filter(r=>r.rt==="Hazard"),r=>r.status==="Closed"],["Actions",Ac,a=>!!a.closedAt],["Incidents",R.filter(r=>r.rt==="Incident"),r=>r.status==="Closed"],["Audit findings",F,f=>f.data.status==="Closed"]];
 const V=L.activities.filter(v=>ids.has(v.project)&&hsIn(v.date));const cnt=t=>V.filter(v=>v.type===t).reduce((s,v)=>s+(+v.count||1),0);
 const si=[["Toolbox talks",cnt("Toolbox talk")],["SWA",hsSum(M,"swa")],["Observations",R.filter(r=>r.rt==="Hazard").length],["Inspections",L.inspections.filter(i=>ids.has(i.project)&&hsIn(i.ts)).length],["Trainings",hsSum(M,"trainings")],["Committee",hsSum(M,"committee")],["Drills",hsSum(M,"drills")]];
 return`<div class="hs-chips">${cs.map(c=>`<button data-hx="country" data-hv="${esc(c)}" aria-pressed="${st.country===c}">${esc(c)}</button>`).join("")}</div>
 <div class="hs-chips sm">${(st.country?byC[st.country]:myProjects()).map(p=>`<button data-hx="proj" data-hv="${p.id}" aria-pressed="${h.proj===p.id}">${esc(p.name)}</button>`).join("")}</div>
 <div class="hs-g6">${hCard("Manpower",`<div class="hk2"><div><b>${hsN(hsSum(last,"empHead"))}</b><small>Employees</small></div><div><b>${hsN(hsSum(last,"conHead"))}</b><small>Contractors</small></div></div>`)}${hCard("Hours worked",`<div class="hk2"><div><b>${hsN(hrs.emp)}</b><small>Employees</small></div><div><b>${hsN(hrs.con)}</b><small>Contractors</small></div></div>`)}
 ${hCard("Safe work hours",`<div class="hk2"><div><b>${hsN(sf.hours)}</b><small>Safe work hours</small></div><div><b>${sf.days}</b><small>Safe days</small></div></div>`)}${hCard("Incident rates",`<div class="hk2"><div><b>${hsRate(lti,hrs.tot).toFixed(2)}</b><small>LTIR</small></div><div><b>${hsRate(rec,hrs.tot).toFixed(2)}</b><small>TRIR</small></div></div>`)}
 ${hCard("Last audit result",`<div class="hbig" style="color:${A?hsBand(A.data.score):"var(--muted)"}">${A?A.data.score+"%":"N/A"}</div>`)}${hCard("PSM score",`<div class="hbig" style="color:${psm?(psm.data.score>=3.5?HC.green:psm.data.score>=3?"#E6B800":HC.red):"var(--muted)"}">${psm?(+psm.data.score).toFixed(2):"N/A"}</div>`)}</div>
 <div class="hs-site"><div>${hCard("Lagging & leading indicators",hsDiamond(P))}</div><div>${hCard("NAVO closure",hVbars(cl.map(c=>c[0]),[{n:"Raised",v:cl.map(c=>c[1].length),c:HC.blue},{n:"Closed",v:cl.map(c=>c[1].filter(c[2]).length),c:HC.lime}],{rate:cl.map(c=>c[1].length?Math.round(c[1].filter(c[2]).length/c[1].length*100):null),legend:1,h:120}))}${hCard("Safety indicators",hVbars(si.map(s=>s[0]),[{n:"Count",v:si.map(s=>s[1]),c:HC.blue}],{h:110}))}</div>
 <div>${hCard("Total injury cases",hHbars(RECORDABLE.map(([s,n,c])=>[n,sev(s),hAt("h","sev:"+s),c])))}${hCard("Last audit findings",hTable(["Element","Severity","Status"],F.sort((a,b)=>b.ts-a.ts).slice(0,6).map(f=>`<tr><td>${esc(f.data.element)}</td><td>${esc(f.data.sev)}</td><td>${esc(f.data.status)}</td></tr>`)))}${hCard("Recent accidents",hTable(["Incident","Date"],R.filter(r=>r.rt==="Incident"&&r.kind!=="Near Miss").slice(0,6).map(r=>`<tr><td>${esc(r.desc||r.kind)}</td><td>${new Date(r.ts).toLocaleDateString("en-GB",{day:"2-digit",month:"short"})}</td></tr>`)))}</div></div>`}

