const BODY_SPOTS={Head:[50,9],Eye:[53,8],Neck:[50,17],Shoulder:[36,22],Arm:[28,36],Hand:[22,50],Finger:[20,55],Back:[60,34],Chest:[50,28],Leg:[44,68],Knee:[44,74],Foot:[42,95]};
function hsBody(counts){const mx=Math.max(1,...Object.values(counts));
 return`<svg viewBox="0 0 100 100" class="hbody"><g fill="#0b6aa8"><circle cx="50" cy="9" r="7"/><rect x="47" y="15" width="6" height="5" rx="2"/><path d="M36 21 Q50 18 64 21 L68 50 L61 50 L60 34 L59 52 L61 98 L53 98 L50 60 L47 98 L39 98 L41 52 L40 34 L39 50 L32 50 Z"/><path d="M36 21 L26 44 L21 55 L25 57 L31 46 L39 32 Z"/><path d="M64 21 L74 44 L79 55 L75 57 L69 46 L61 32 Z"/></g>
 ${Object.entries(counts).filter(([k,v])=>v&&BODY_SPOTS[k]).map(([k,v])=>{const[x,y]=BODY_SPOTS[k];return`<circle class="hot" ${hAt("h","body:"+k)} cx="${x}" cy="${y}" r="${2.5+v/mx*5}" fill="${HC.red}" opacity=".85"><title>${k}: ${v}</title></circle>`}).join("")}</svg>`}
function hsInj(P){const R=hsR(P);const inj=R.filter(r=>sevOf(r));const hrs=hsHours(P);const tg=hsTargets();const sev=s=>inj.filter(r=>sevOf(r)===s);
 const fat=sev("Fatality").sort((a,b)=>b.ts-a.ts),lti=sev("Lost Time").sort((a,b)=>b.ts-a.ts);const lastF=L.reports.filter(r=>hsIds(P).has(r.project)&&sevOf(r)==="Fatality").sort((a,b)=>b.ts-a.ts)[0],lastL=L.reports.filter(r=>hsIds(P).has(r.project)&&sevOf(r)==="Lost Time").sort((a,b)=>b.ts-a.ts)[0];
 const dt=r=>r?new Date(r.ts).toLocaleDateString("en-GB",{day:"2-digit",month:"short",year:"numeric"}):"N/A";
 const ltir=hsRate(fat.length+lti.length,hrs.tot),trir=hsRate(inj.filter(r=>sevOf(r)!=="First Aid").length,hrs.tot);
 const byC=hsGroup(P,"country"),cs=Object.keys(byC).sort();const geo=(sevs,t)=>cs.map(c=>{const r=hsR(byC[c]).filter(x=>sevs.includes(sevOf(x))).length;return[c,hsRate(r,hsHours(byC[c]).tot),t]});
 const cnt=(arr,f)=>{const o={};arr.forEach(r=>{const k=f(r)||"Not recorded";o[k]=(o[k]||0)+1});return Object.entries(o).sort((a,b)=>b[1]-a[1])};
 const bp=Object.fromEntries(cnt(inj,r=>r.bodyPart));
 return`<div class="hs-inj"><div class="hs-2">${hCard("Total fatalities",`<div class="hk2"><div><b style="color:${HC.purple}">${fat.length}</b></div><div><small>Last fatality date</small><em>${dt(lastF)}</em><small>Last fatality site</small><em>${lastF?esc(projName(lastF.project)):"N/A"}</em></div></div>`)}${hCard("Total LTIs",`<div class="hk2"><div><b style="color:${HC.purple}">${lti.length}</b></div><div><small>Last LTI date</small><em>${dt(lastL)}</em><small>Last LTI site</small><em>${lastL?esc(projName(lastL.project)):"N/A"}</em></div></div>`)}
 ${hCard("LTI rate",hGauge(ltir,tg.ltir,+(tg.ltir*1.2).toFixed(2),"Overall")+`<h4>Geo-wise</h4>`+hsTgtBars(geo(["Lost Time","Fatality"],tg.ltir)))}${hCard("Injury rate (TRIR)",hGauge(trir,tg.trir,+(tg.trir*1.5).toFixed(2),"Overall")+`<h4>Geo-wise</h4>`+hsTgtBars(geo(["Lost Time","Fatality","Restricted Work","Medical Treatment"],tg.trir)))}</div>
 <div>${hCard("Injured persons",hDonut([["Contractor",inj.filter(r=>r.personType!=="Employee").length,HC.blue],["Employee",inj.filter(r=>r.personType==="Employee").length,HC.navy]],inj.length,"persons"))}${hCard("Total injury cases",hDonut(RECORDABLE.map(([s,n,c])=>[n,sev(s).length,c]),inj.length,"cases",n=>hAt("h","sev:"+RECORDABLE.find(r=>r[1]===n)[0])))}</div>
 <div>${hCard("Site-wise injuries",hTable(["Site","Injuries"],cnt(inj,r=>projName(r.project)).map(([k,v])=>`<tr class="hot" ${hAt("proj",L.projects.find(p=>p.name===k)?.id||"")}><td>${esc(k)}</td><td class="r">${v}</td></tr>`),{h:220}))}${hCard("Geo-wise injuries",hVbars(cs,[{n:"Injuries",v:cs.map(c=>hsR(byC[c]).filter(r=>sevOf(r)).length),c:HC.navy}],{h:110,attr:i=>hAt("country",cs[i])}))}</div>
 <div>${hCard("Injury type & body part",hTable(["Injury type","Injuries"],cnt(inj,r=>r.injuryType).map(([k,v])=>`<tr><td>${esc(k)}</td><td class="r">${v}</td></tr>`),{h:170})+hsBody(bp)+hTable(["Body part","Injuries"],Object.entries(bp).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<tr class="hot" ${hAt("h","body:"+k)}><td>${esc(k)}</td><td class="r">${v}</td></tr>`),{h:120}))}</div></div>`}
function hsTgtBars(rows){if(!rows.length)return hEmpty();const mx=Math.max(...rows.map(r=>Math.max(r[1],r[2])),.01);return`<div class="hb">${rows.map(([n,v,t])=>`<div class="hb-r"><span class="hb-l">${esc(n)}</span><span class="hb-t"><i style="width:${t/mx*100}%;background:#ffc0c8"></i><i style="position:absolute;left:0;top:3px;bottom:3px;width:${v/mx*100}%;background:${v>t?HC.red:HC.blue}"></i></span><span class="hb-v">${v.toFixed(2)}</span></div>`).join("")}</div>${hLeg(["Target","Actual"],["#ffc0c8",HC.blue])}`}
function hsInc(P){const h=hsInit();const mode=h.sel.inc||"Accident";const R=hsR(P).filter(r=>r.rt==="Incident"&&(mode==="Near Miss"?r.kind==="Near Miss":r.kind!=="Near Miss"));const all=hsR(P).filter(r=>r.rt==="Incident");
 const byC=hsGroup(P,"country"),cs=Object.keys(byC).sort();const cnt=(arr,f)=>{const o={};arr.forEach(r=>{const k=f(r)||"Not recorded";o[k]=(o[k]||0)+1});return Object.entries(o).sort((a,b)=>b[1]-a[1])};
 const sites=cnt(R,r=>projName(r.project)).slice(0,25);
 return`<div class="hs-inc"><div><div class="hs-incTop"><div class="hseg">${["Accident","Near Miss"].map(k=>`<button data-hsel="inc" data-v="${k}" aria-pressed="${k===mode}">${k}</button>`).join("")}</div>${hKpi("Total accidents",all.filter(r=>r.kind!=="Near Miss").length,{color:HC.red})}${hKpi("Total near miss",all.filter(r=>r.kind==="Near Miss").length,{color:HC.red})}</div>
 ${hCard("Incidents by geo",hVbars(cs,[{n:"Incidents",v:cs.map(c=>R.filter(r=>byC[c].some(p=>p.id===r.project)).length),c:HC.red}],{h:100,attr:i=>hAt("country",cs[i])}))}${hCard("Incidents by categories",hVbars(cnt(R,incCat).map(x=>x[0]),[{n:"Incidents",v:cnt(R,incCat).map(x=>x[1]),c:"#B63B3B"}],{h:100,attr:i=>hAt("h","inc:"+cnt(R,incCat)[i][0])}))}${hCard("Incidents by injury type",hVbars(RECORDABLE.map(r=>r[1]),[{n:"Cases",v:RECORDABLE.map(([s])=>R.filter(r=>sevOf(r)===s).length),c:"#B63B3B"}],{h:100,attr:i=>hAt("h","sev:"+RECORDABLE[i][0])}))}</div>
 <div><div class="hs-2">${hCard("Incidents by sites",hLine(sites.map(s=>s[0].split(" ").slice(-2).join(" ")),[{n:"Incidents",v:sites.map(s=>s[1]),c:HC.blue}],{area:1,vals:1,h:110}))}${hCard("Incident classifications",hDonut(INC_CLASS.map((c,i)=>[c,R.filter(r=>r.incClass===c).length,["#7A1F2B",HC.red,"#E07A7A","#F4A9A8"][i]]).concat([["N/A",R.filter(r=>!r.incClass).length,"#F8D7D7"]]),R.length,"incidents"))}</div>
 ${hCard("Incident list",hTable(["Case no","Incident","Site","Category","Date"],R.slice(0,200).map(r=>`<tr><td class="id">${String(r.id).slice(0,8).toUpperCase()}</td><td>${esc(r.desc||r.kind)}</td><td>${esc(projName(r.project))}</td><td>${esc(incCat(r))}</td><td>${new Date(r.ts).toLocaleDateString("en-GB",{day:"2-digit",month:"short",year:"numeric"})}</td></tr>`),{h:420}))}</div></div>`}

/* ---------- 5. Audits ---------- */
const SEVCOL={"Best Practice":HC.blue,Major:HC.navy,Minor:"#2F4F8F",Moderate:"#F2B600",Observation:HC.orange,Significant:"#C00000","Opportunity for improvement":HC.purple};
function hsAudit(P,which){const F=hsRec(P,"finding").filter(f=>f.data.audit===which);const byC=hsGroup(P,"country"),cs=Object.keys(byC).sort();const cnt=(arr,f)=>{const o={};arr.forEach(r=>{const k=f(r)||"Other";o[k]=(o[k]||0)+1});return Object.entries(o).sort((a,b)=>b[1]-a[1])};
 const bySite=cnt(F,f=>projName(f.project)).slice(0,20);const sevs=Object.keys(SEVCOL).filter(s=>F.some(f=>f.data.sev===s));const top=cnt(F,f=>f.data.element).slice(0,10);
 const closed=F.filter(f=>f.data.status==="Closed"),od=F.filter(f=>f.data.status!=="Closed"&&f.data.due&&f.data.due<Date.now());
 if(which==="Process Safety"){const S=hsRec(P,"audit").filter(a=>a.data.audit==="Process Safety");const lastBy={};S.forEach(a=>{if(!lastBy[a.project]||a.ts>lastBy[a.project].ts)lastBy[a.project]=a});const L2=Object.values(lastBy).sort((a,b)=>b.data.score-a.data.score);const tg=hsTargets().psm;
  const col=v=>v>=3.5?HC.green:v>=3?"#F2B600":HC.red;const el=PSM_ELEMENTS.map(e=>[e,L2.length?L2.reduce((s,a)=>s+(+(a.data.elements||{})[e]||0),0)/L2.length:0]).sort((a,b)=>b[1]-a[1]);
  const geo=cs.map(c=>{const x=L2.filter(a=>byC[c].some(p=>p.id===a.project));return[c,x.length?x.reduce((s,a)=>s+ +a.data.score,0)/x.length:null]}).filter(x=>x[1]!=null);
  return`${hCard("PSM result",hsColBars(L2.map(a=>[projName(a.project),+(+a.data.score).toFixed(2),col(+a.data.score),hAt("proj",a.project)]),{target:tg,max:5})+hLeg(["≥ 3.5","3.0 – 3.5","< 3.0","Target"],[HC.green,"#F2B600",HC.red,HC.red]))}
  <div class="hs-2b">${hCard("Geo-wise score",hsColBars(geo.map(([c,v])=>[c,+v.toFixed(2),col(v),hAt("country",c)]),{max:5}))}${hCard("Element score",hsColBars(el.map(([e,v])=>[e,+v.toFixed(2),col(v)]),{max:5}))}</div>`}
 if(which==="OSHE"){const S=hsRec(P,"audit").filter(a=>a.data.audit==="OSHE");const lastBy={};S.forEach(a=>{if(!lastBy[a.project]||a.ts>lastBy[a.project].ts)lastBy[a.project]=a});const L2=Object.values(lastBy).sort((a,b)=>b.data.score-a.data.score);
  const band=v=>v>=95?["Outstanding","#1E8F3A"]:v>=81?["Managed",HC.lime]:v>=71?["Adequate","#FFE699"]:v>=60?["Reactive",HC.orange]:["Attention",HC.red];
  const geo=cs.map(c=>{const x=L2.filter(a=>byC[c].some(p=>p.id===a.project));return[c,x.length?Math.round(x.reduce((s,a)=>s+ +a.data.score,0)/x.length):null]}).filter(x=>x[1]!=null);
  return`${hCard("Audit result",hsColBars(L2.map(a=>[projName(a.project),+a.data.score,band(+a.data.score)[1],hAt("proj",a.project)]),{max:100})+hLeg(["95–100 Outstanding","81–94 Managed","71–80 Adequate","60–70 Reactive","< 60 Attention"],["#1E8F3A",HC.lime,"#FFE699",HC.orange,HC.red]))}
  <div class="hs-2b">${hCard("Top-10 element findings",hVbars(top.map(t=>t[0]),sevs.map(s=>({n:s,v:top.map(t=>F.filter(f=>f.data.element===t[0]&&f.data.sev===s).length),c:SEVCOL[s]})),{stack:1,legend:1,h:150}))}<div>${hCard("Geo-wise score",hsColBars(geo.map(([c,v])=>[c,v,band(v)[1],hAt("country",c)]),{max:100}))}${hCard("Region-wise findings",hTreemap(sevs.map(s=>[s,F.filter(f=>f.data.sev===s).length,SEVCOL[s]])))}</div></div>`}
 return`${hCard("Audit findings",hVbars(bySite.map(s=>s[0]),[{n:"Findings",v:bySite.map(s=>s[1]),c:HC.violet}],{h:130,attr:i=>hAt("proj",L.projects.find(p=>p.name===bySite[i][0])?.id||"")}),{right:hsN(F.length)+" findings"})}
 <div class="hs-aud"><div>${hCard("Type-wise findings",`<div class="hs-2">${hDonut(cnt(F,f=>f.data.ftype).map(([k,v],i)=>[k,v,[HC.blue,HC.navy,HC.orange][i%3]]),F.length,"findings")}<div><div class="hk"><small>Closure rate</small><b style="color:${HC.violet}">${F.length?Math.round(closed.length/F.length*100):0}%</b></div>${hHbars([["Closed",closed.length,"",HC.violet],["Open",F.length-closed.length-od.length,"",HC.violet],["Overdue",od.length,"",HC.red]])}</div></div>`)}</div>
 ${hCard("Geo-wise findings",hVbars(cs,[{n:"Findings",v:cs.map(c=>F.filter(f=>byC[c].some(p=>p.id===f.project)).length),c:HC.violet}],{h:110,attr:i=>hAt("country",cs[i])}))}</div>
 <div class="hs-2b">${hCard("Top-10 element findings",hVbars(top.map(t=>t[0]),sevs.map(s=>({n:s,v:top.map(t=>F.filter(f=>f.data.element===t[0]&&f.data.sev===s).length),c:SEVCOL[s]})),{stack:1,legend:1,h:150}))}${hCard("Severity of findings",hTreemap(sevs.map(s=>[s,F.filter(f=>f.data.sev===s).length,SEVCOL[s]])))}</div>`}
function hsColBars(rows,o={}){if(!rows.length)return hEmpty();const h=130,n=rows.length,W=Math.max(300,n*48),pad=18,mx=o.max||Math.max(...rows.map(r=>r[1]))*1.15,bw=W/n,y=v=>pad+h-v/mx*h;let g="";
 rows.forEach(([nm,v,c,at],i)=>{g+=`<rect x="${i*bw+bw*.12}" y="${y(v)}" width="${bw*.76}" height="${pad+h-y(v)}" fill="${c}" ${at||""} ${at?'class="hot"':""}><title>${esc(nm)}: ${v}</title></rect><text x="${i*bw+bw/2}" y="${y(v)+14}" text-anchor="middle" class="hv w">${v}</text><text x="${i*bw+bw/2}" y="${pad+h+13}" text-anchor="middle" class="hx" transform="rotate(-25 ${i*bw+bw/2} ${pad+h+13})">${esc(nm.length>14?nm.slice(0,13)+"…":nm)}</text>`;if(o.target)g+=`<circle cx="${i*bw+bw/2}" cy="${y(o.target)}" r="3" fill="${HC.red}"/>`});
 if(o.target)g+=`<line x1="0" x2="${W}" y1="${y(o.target)}" y2="${y(o.target)}" stroke="${HC.red}" stroke-dasharray="5 4"/>`;return`<div class="hsvg"><svg viewBox="0 0 ${W} ${pad+h+40}" style="max-height:${Math.round((pad+h+40)*1.5)}px">${g}</svg></div>`}

/* ---------- 6. Accident & audit analysis (decomposition tree) ---------- */
function hsTree(P,which){const h=hsInit();const key=which;const path=h.dt[key]||(h.dt[key]=[]);
 const items=which==="acc"?hsR(P).filter(r=>r.rt==="Incident"):hsRec(P,"finding");const pr=id=>L.projects.find(p=>p.id===id)||{};
 const levels=which==="acc"?[["Country",r=>pr(r.project).country],["Platform",r=>pr(r.project).platform||"Construction"],["Site",r=>pr(r.project).name],["Category",r=>incCat(r)],["Cause / high-energy",r=>r.cat||"Not classified"]]
  :[["Country",r=>pr(r.project).country],["Site",r=>pr(r.project).name],["Audit",r=>r.data.audit],["Element",r=>r.data.element],["Severity",r=>r.data.sev]];
 let cur=items;const cols=[`<div class="dt-col"><div class="dt-h">${which==="acc"?"Total incidents":"Total findings"}</div><div class="dt-n on"><i style="width:100%"></i><span>All</span><b>${items.length}</b></div></div>`];
 for(let i=0;i<levels.length;i++){const[name,f]=levels[i];const g={};cur.forEach(r=>{const k=f(r)||"—";g[k]=(g[k]||0)+1});const ent=Object.entries(g).sort((a,b)=>b[1]-a[1]);const tot=cur.length||1;
  cols.push(`<div class="dt-col"><div class="dt-h">${name}${path[i]!=null?` <button class="dt-x" data-dtx="${key}" data-i="${i}">×</button>`:""}</div>${ent.map(([k,v])=>`<div class="dt-n hot ${path[i]===k?"on":""}" data-dt="${key}" data-i="${i}" data-v="${esc(k)}"><i style="width:${v/tot*100}%"></i><span>${esc(k)}</span><b>${v} · ${(v/tot*100).toFixed(1)}%</b></div>`).join("")}</div>`);
  if(path[i]==null)break;cur=cur.filter(r=>(f(r)||"—")===path[i])}
 return hCard(which==="acc"?"Accident analysis":"Audit analysis",`<p class="hs-note">Click a value to break it down by the next level. Click × to go back.</p><div class="dt">${cols.join("")}</div>`)}

/* ---------- 7. Annual KPI ---------- */
function hsKpi(P,tab){if(tab!=="all")P=P.filter(p=>(p.platform||"Construction")===tab);const h=hsInit(),y=h.y;const byC=hsGroup(P,"country"),cs=Object.keys(byC).sort();const cc=c=>HPAL[cs.indexOf(c)%HPAL.length];const now=new Date();const nM=y===now.getFullYear()?now.getMonth()+1:12;const mons=HMON.slice(0,nM);
 const per=(fn)=>cs.map(c=>({n:c,v:mons.map((_,i)=>fn(byC[c],i+1)),c:cc(c)}));const Rm=(ps,mo)=>L.reports.filter(r=>hsIds(ps).has(r.project)&&hsYM(r.ts)[0]===y&&hsYM(r.ts)[1]===mo);const Mm=(ps,mo)=>hsMon(ps,true).filter(m=>m.data.month===hsKey(y,mo));
 const tr=(ps,mo)=>{const hrs=hsSum(Mm(ps,mo),"empHours")+hsSum(Mm(ps,mo),"conHours");const n=Rm(ps,mo).filter(r=>["Fatality","Lost Time","Restricted Work","Medical Treatment"].includes(sevOf(r))).length;return hrs?hsRate(n,hrs):null};
 const sh=(ps,mo)=>{const k=hsKey(y,mo);const s=ps.filter(p=>L.reports.some(r=>r.project===p.id&&inMonth(r.ts,k))).map(p=>monthCard(p.id,k).total);return s.length?+(s.reduce((a,b)=>a+b,0)/s.length).toFixed(1):null};
 const C=hsCards(P);const cnt=s=>C.filter(x=>x.status===s).length;const ids=hsIds(P);
 const visits=mons.map((_,i)=>L.activities.filter(v=>ids.has(v.project)&&v.type==="Leadership walkthrough"&&hsYM(v.date)[0]===y&&hsYM(v.date)[1]===i+1).reduce((s,v)=>s+(+v.count||1),0));const target=P.reduce((s,p)=>s+(+p.planWalk||0),0);
 const cum=(ps,mo)=>{let a=0,b=0;for(let i=1;i<=mo;i++){a+=hsSum(Mm(ps,i),"trainHours");b+=hsSum(Mm(ps,i),"trainPlan")}return b?Math.min(100,Math.round(a/b*100)):null};
 const cc2=mons.map((_,i)=>{const m=Mm(P,i+1);const t=hsSum(m,"ccChecks");return t?[hsPct(t-hsSum(m,"ccAtRisk"),t),hsPct(hsSum(m,"ccAtRisk"),t)]:[null,null]});
 return`<div class="hs-kpi">${hCard("1. Fatality & permanent impairment injury",hLine(mons,per((ps,mo)=>Rm(ps,mo).filter(r=>sevOf(r)==="Fatality"||r.ai?.pfpi&&r.rt==="Incident").length),{h:110}))}
 ${hCard("2. Total recordable injury rate (TRIR)",hLine(mons,per(tr),{band:[0,hsTargets().trir],h:110,vals:0}))}${hCard("3. Site health indicator",hLine(mons,per(sh),{max:100,h:110}))}
 ${hCard("HSSE system health",`<div class="hsys">${Object.entries(HSTAT).map(([k,[i,c]])=>`<div><small>${k}</small><b><span style="color:${c}">${i}</span> ${cnt(k)}</b></div>`).join("")}</div>`)}
 ${hCard("4. Leadership visits",hVbars(mons,[{n:"Visits",v:visits,c:HC.teal},{n:"Target",v:mons.map(()=>target),c:"#7fd1a8"}],{legend:1,h:110,bw:40}))}${hCard("5. Leadership review of PFPI events",hVbars(mons,[{n:"Reviewed",v:mons.map((_,i)=>hsSum(Mm(P,i+1),"pfpiReviewed")),c:HC.teal}],{h:110}))}
 ${hCard("6. Critical safety checklist analysis",hLine(mons,[{n:"Safe",v:cc2.map(x=>x[0]),c:"#1E8F3A"},{n:"At risk",v:cc2.map(x=>x[1]),c:HC.lime}],{max:110,vals:1,unit:"%",h:110,legend:1}))}${hCard("7. Training pathway (cumulative % of plan)",hLine(mons,per(cum),{band:[50,100],max:100,h:110}))}</div>`}

/* ---------- 8. E&S ---------- */
function hsGriev(P){const G=hsRec(P,"grievance");const s=k=>G.filter(g=>g.data.status===k).length;const now=Date.now();const od=G.filter(g=>g.data.status!=="Closed"&&now-g.ts>28*864e5).length;
 const cnt=(arr,f)=>{const o={};arr.forEach(r=>{const k=f(r)||"Other";o[k]=(o[k]||0)+1});return Object.entries(o).sort((a,b)=>b[1]-a[1])};const days=g=>((g.data.closedTs||now)-g.ts)/864e5;
 const tile=(ic,v,l,c,p)=>`<div class="hs-tile"><span class="ic" style="color:${c}">${ic}</span><div><b>${hsN(v)}</b><small style="color:${c}">${l}</small></div>${p!=null?`<em style="color:${c}">${p}%</em>`:""}</div>`;
 return`<div class="hs-tiles">${tile("▤",G.length,"Total cases",HC.violet)}<span>=</span>${tile("✚",s("New"),"New cases",HC.blue,hsPct(s("New"),G.length))}<span>+</span>${tile("◷",s("In progress"),"In progress","#E6A000",hsPct(s("In progress"),G.length))}<span>+</span>${tile("✔",s("Closed"),"Closed",HC.green,hsPct(s("Closed"),G.length))}<span>⊃</span>${tile("▣",od,"Overdue",HC.red,hsPct(od,G.length))}</div>
 <div class="hs-2b">${hCard("Site-wise grievances",hVbars(cnt(G,g=>projName(g.project)).map(x=>x[0]),[{n:"Grievances",v:cnt(G,g=>projName(g.project)).map(x=>x[1]),c:"#E8E3F5"}],{h:120,attr:i=>hAt("proj",L.projects.find(p=>p.name===cnt(G,g=>projName(g.project))[i][0])?.id||"")}),{cls:"dark"})}
 ${hCard("KPI · grievance resolution",hHbars([["On time (< 14 days)",G.filter(g=>g.data.status==="Closed"&&days(g)<14).length,"","#79C98E"],["Attention (14 – 28 days)",G.filter(g=>days(g)>=14&&days(g)<=28).length,"","#F5C54A"],["Overdue (> 28 days)",G.filter(g=>days(g)>28).length,"","#F07C7C"]])+`<p class="hs-note">On time: closed within 14 days. Attention: resolved, or still open, between 14 and 28 days. Overdue: open or resolved after 28 days.</p>`)}</div>
 <div class="hs-3">${hCard("Grievance categorisation",hHbars(cnt(G,g=>g.data.category).map(([k,v])=>[k,v,"","#B9A6E8"])))}${hCard("Business categorisation",hHbars(cnt(G,g=>L.projects.find(p=>p.id===g.project)?.division).map(([k,v])=>[k,v,"","#B9A6E8"])))}${hCard("Visibility by contractor",hVbars(cnt(G,g=>g.data.epc).map(x=>x[0]),[{n:"Grievances",v:cnt(G,g=>g.data.epc).map(x=>x[1]),c:"#B9A6E8"}],{h:120}))}</div>`}
function hsAccom(P){const A=hsRec(P,"accommodation");const lastBy={};A.forEach(a=>{if(!lastBy[a.project]||a.ts>lastBy[a.project].ts)lastBy[a.project]=a});const X=Object.values(lastBy);const s=k=>X.reduce((t,a)=>t+(+a.data[k]||0),0);
 const items=s("compliant")+s("nonCompliant")+s("partial");const avg=X.length?Math.round(X.reduce((t,a)=>t+ +a.data.score,0)/X.length):0;const sel=hsInit().sel.accom||"Category";
 const agg=k=>{const o={};X.forEach(a=>Object.entries(a.data[k]||{}).forEach(([n,v])=>o[n]=(o[n]||0)+ +v));const t=Object.values(o).reduce((a,b)=>a+b,0)||1;return Object.entries(o).sort((a,b)=>b[1]-a[1]).map(([n,v])=>[n,Math.round(v/t*100)])};
 const tile=(ic,v,l,c,p)=>`<div class="hs-tile"><span class="ic" style="color:${c}">${ic}</span><div><b>${hsN(v)}</b><small>${l}</small></div>${p!=null?`<em style="color:${c}">${p}%</em>`:""}</div>`;
 const sc=X.sort((a,b)=>b.data.score-a.data.score);
 return`<div class="hs-tiles">${tile("▤",A.length,"Total assessments",HC.violet)}${tile("⌂",s("accommodations"),"Total accommodations",HC.green)}${tile("☺",s("workers"),"Total workers",HC.blue)}${tile("✔",s("compliant"),"Compliant",HC.green,hsPct(s("compliant"),items))}${tile("!",s("nonCompliant"),"Non-compliant",HC.red,hsPct(s("nonCompliant"),items))}${tile("◐",s("partial"),"Partially compliant","#E6A000",hsPct(s("partial"),items))}${tile("⛨",s("actions"),"Total actions",HC.green)}</div>
 <div class="hs-2b">${hCard("Site scores",`<div class="hs-acc"><div>${hGauge(avg,90,100,"Avg. site score").replace(/(\d+)\.00</,"$1%<")}</div>${hsColBars(sc.map(a=>[projName(a.project),+a.data.score,a.data.score>=95?"#1E8F3A":a.data.score>=90?"#E6A000":HC.red,hAt("proj",a.project)]),{max:100})}</div>`,{cls:"dark"})}
 ${hCard("Non-compliance analysis",`<div class="hseg">${["Category","Item"].map(k=>`<button data-hsel="accom" data-v="${k}" aria-pressed="${k===sel}">${k}</button>`).join("")}</div>`+hHbars(agg(sel==="Category"?"ncCats":"ncItems").map(([n,v])=>[n,v,"","#B9A6E8"]),{fmt:v=>v+"%"}))}</div>
 <div class="hs-3">${hCard("Accommodation managed by",hHbars((()=>{const o={};X.forEach(a=>o[a.data.managedBy]=(o[a.data.managedBy]||0)+1);return Object.entries(o).map(([k,v])=>[k,Math.round(v/X.length*100),"","#B9A6E8"])})(),{fmt:v=>v+"%"}))}${hCard("Indicative demographics",hVbars(agg("nations").map(x=>x[0]),[{n:"%",v:agg("nations").map(x=>x[1]),c:"#B9A6E8"}],{h:110}))}${hCard("Site accommodations",hTable(["Site","Workers","Camps"],sc.map(a=>`<tr><td>${esc(projName(a.project))}</td><td class="r">${hsN(a.data.workers)}</td><td class="r">${hsN(a.data.camps)}</td></tr>`),{h:220}))}</div>`}

/* ---------- drill list ---------- */
function hsDrillRows(P,k){const R=hsR(P);const ids=hsIds(P);
 if(k.startsWith("sev:"))return["Injuries · "+k.slice(4),R.filter(r=>sevOf(r)===k.slice(4))];if(k.startsWith("inc:"))return["Incidents · "+k.slice(4),R.filter(r=>incCat(r)===k.slice(4))];
 if(k.startsWith("body:"))return["Injuries · "+k.slice(5),R.filter(r=>sevOf(r)&&r.bodyPart===k.slice(5))];if(k==="nearmiss")return["Near misses",R.filter(r=>r.kind==="Near Miss")];if(k==="hazards")return["Unsafe acts & conditions",R.filter(r=>r.rt==="Hazard")];
 if(k==="insp")return["Inspections",L.inspections.filter(i=>ids.has(i.project)&&hsIn(i.ts)).map(i=>({ts:i.ts,desc:i.tpl+" · "+i.fails+" of "+i.items+" items at risk",project:i.project,kind:"Inspection",status:i.fails?"At risk":"Safe"}))];
 if(k==="walks"||k==="tbt"){const t=k==="walks"?"Leadership walkthrough":"Toolbox talk";return[t+"s",L.activities.filter(v=>ids.has(v.project)&&hsIn(v.date)&&v.type===t).map(v=>({ts:v.date,desc:t+" × "+(v.count||1),project:v.project,kind:t,status:"Done"}))]}
 if(k==="audits")return["Audit findings",hsRec(P,"finding").map(f=>({ts:f.ts,desc:f.data.element+" · "+f.data.sev,project:f.project,kind:f.data.audit,status:f.data.status}))];return["Records",[]]}
function hsDrill(P){const h=hsInit();if(!h.drill)return"";const[t,rows]=hsDrillRows(P,h.drill);
 return`<div class="hc hs-drill"><div class="hc-h"><b>${esc(t)} <small>${rows.length} record${rows.length===1?"":"s"}</small></b><button class="btn" data-hdrill-close>Close</button></div>${hTable(["Date","Description","Type","Project","Status"],rows.slice(0,300).map(r=>`<tr><td class="id">${new Date(r.ts).toLocaleDateString("en-GB",{day:"2-digit",month:"short",year:"2-digit"})}</td><td>${esc(r.desc||"—")}</td><td>${esc(r.kind||r.rt||"")}</td><td>${esc(projName(r.project))}</td><td>${esc(r.status||"")}</td></tr>`),{h:360,empty:"Nothing to show for this selection."})}</div>`}

/* ---------- page ---------- */
function hsFilters(){const h=hsInit();const P=myProjects();const yrs=[...new Set(L.reports.map(r=>new Date(r.ts).getFullYear()).concat((L.records||[]).map(r=>new Date(r.ts).getFullYear()),[new Date().getFullYear()]))].sort((a,b)=>b-a);
 const bizs=[...new Set(P.filter(p=>!h.plat||(p.platform||"Construction")===h.plat).map(p=>p.division).filter(Boolean))].sort();
 return`<div class="hs-filt"><label>Year<select data-hf="y">${yrs.map(y=>`<option ${y===h.y?"selected":""}>${y}</option>`).join("")}</select></label><label>Month<select data-hf="m"><option value="0">All (YTD)</option>${HMON.map((m,i)=>`<option value="${i+1}" ${h.m===i+1?"selected":""}>${m}</option>`).join("")}</select></label>
 <label>Country<select data-hf="country"><option value="">All</option>${COUNTRIES.map(c=>`<option ${st.country===c?"selected":""}>${esc(c)}</option>`).join("")}</select></label><label>Platform<select data-hf="plat"><option value="">All</option>${PLATFORMS.map(c=>`<option ${h.plat===c?"selected":""}>${esc(c)}</option>`).join("")}</select></label>
 <label>Business<select data-hf="biz"><option value="">All</option>${bizs.map(c=>`<option ${h.biz===c?"selected":""}>${esc(c)}</option>`).join("")}</select></label><label>Project<select data-hf="proj"><option value="">All</option>${P.filter(p=>(!st.country||p.country===st.country)&&(!h.plat||(p.platform||"Construction")===h.plat)&&(!h.biz||p.division===h.biz)).map(p=>`<option value="${p.id}" ${h.proj===p.id?"selected":""}>${esc(p.name)}</option>`).join("")}</select></label></div>`}
function hsse(){const g=liveGate();if(g)return g;if(myRole()==="worker")return liveTag()+`<div class="panel"><h2>The HSSE dashboard is for supervisors, HSE and leadership</h2></div>`;
 const h=hsInit();const sec=HSEC.find(s=>s[0]===h.sec)||HSEC[0];const tab=h.tab[sec[0]]||sec[2][0][0];const P=hsP();
 const body={exec:{sum:hsExecSum,close:hsClosure,stats:hsStats,waste:hsWaste},health:{card:hsHealthCard,actual:P=>hsMatrix(P,"actual"),ind:P=>hsMatrix(P,"ind"),proj:hsProjDetail},site:{site:hsSite},inj:{inj:hsInj,inc:hsInc},
  aud:{corp:P=>hsAudit(P,"Corporate"),psm:P=>hsAudit(P,"Process Safety"),oshe:P=>hsAudit(P,"OSHE")},acc:{acc:P=>hsTree(P,"acc"),aud:P=>hsTree(P,"aud")},kpi:{all:P=>hsKpi(P,"all"),Construction:P=>hsKpi(P,"Construction"),"Non-Construction":P=>hsKpi(P,"Non-Construction")},es:{griev:hsGriev,accom:hsAccom}}[sec[0]][tab];
 const noData=!(L.records||[]).length;const active=[st.country,h.plat,h.biz,h.proj&&projName(h.proj),h.m&&HMON[h.m-1]].filter(Boolean);
 return liveTag()+`<div class="hs">
 <nav class="hs-nav"><div class="hs-brand">${brand().hide?"":`<span class="hs-mark">${brand().logo?`<img src="${brand().logo}" alt="">`:NAVO_MARK}</span>`}<span class="hs-logo">${esc(brand().name)}</span><div class="hs-letters"><i style="background:#1565C0">H</i><i style="background:#F9A825">S</i><i style="background:#C62828">S</i><i style="background:#2E7D32">E</i></div><b>Global HSSE Dashboard</b></div><button class="hs-back" data-go="live">← NAVO menu</button>${HSEC.map(s=>`<button data-hsec="${s[0]}" aria-current="${s[0]===sec[0]}">${s[1]}</button>`).join("")}<button class="hs-entry" data-go="hdata">+ Enter HSSE data</button></nav>
 <section class="hs-main-wrap"><div class="hs-band"><div class="hs-sectitle">${sec[1]}</div><div class="hs-crumb">${esc(hsTitle())}</div><div class="hs-dl">${["xlsx","docx","pptx"].map((f,i)=>`<button class="btn" data-export="${f}">${["Excel","Word","PowerPoint"][i]}</button>`).join("")}</div></div>
 <div class="hs-frame"><aside class="hs-strip"><button title="Reset filters" data-hreset>⟲</button><button title="Filters" data-hfilt aria-pressed="${h.filt}">☰</button><span>Global HSSE Dashboard</span></aside>
 <div class="hs-body">${h.filt?hsFilters():""}${active.length?`<div class="hs-active">Filtered: ${active.map(esc).join(" · ")} <button data-hreset>Clear</button></div>`:""}
 ${noData?`<div class="hs-note hs-warn">Man-hours, training, permits, waste, audits, grievances and accommodation data appear here once entered on <button class="linkbtn" data-go="hdata">Enter HSSE data</button> (or load demo data in Structure & settings). Reports, actions, inspections and activities are already live.</div>`:""}
 ${hsDrill(P)}${body(P)}</div></div>
 <div class="hs-tabs">${sec[2].map(([k,l])=>`<button data-htab="${k}" aria-selected="${k===tab}">${l}</button>`).join("")}</div></section></div>`}

/* ---------- interactions ---------- */
document.addEventListener("click",e=>{const t=e.target.closest("[data-hsec],[data-htab],[data-hx],[data-hsel]:not(select),[data-hreset],[data-hfilt],[data-hdrill-close],[data-dt],[data-dtx],[data-hdel],[data-hclose],[data-hdtab]");if(!t||!st.hs&&!t.dataset.hdtab)return;const h=hsInit();
 if(t.dataset.hsec){h.sec=t.dataset.hsec;h.drill=null;render();window.scrollTo(0,0);return}
 if(t.dataset.htab){h.tab[h.sec]=t.dataset.htab;h.drill=null;render();return}
 if(t.dataset.hdtab){h.dtab=t.dataset.hdtab;render();return}
 if(t.hasAttribute("data-hreset")){st.country="";h.plat=h.biz=h.proj="";h.m=0;h.drill=null;h.dt={};const s=document.getElementById("country");if(s)s.value="";render();return}
 if(t.hasAttribute("data-hfilt")){h.filt=!h.filt;render();return}
 if(t.hasAttribute("data-hdrill-close")){h.drill=null;render();return}
 if(t.dataset.dt){const p=h.dt[t.dataset.dt]||[];const i=+t.dataset.i;p.length=i;p[i]=t.dataset.v;h.dt[t.dataset.dt]=p;render();return}
 if(t.dataset.dtx){const p=h.dt[t.dataset.dtx]||[];p.length=+t.dataset.i;render();return}
 if(t.dataset.hsel){h.sel[t.dataset.hsel]=t.dataset.v;render();return}
 if(t.dataset.hdel){hsDelete(t.dataset.hdel,t);return}
 if(t.dataset.hclose){hsCloseRec(t.dataset.hclose);return}
 if(t.dataset.hx){const k=t.dataset.hx,v=t.dataset.hv;if(k==="country"){st.country=st.country===v?"":v;h.proj="";const s=document.getElementById("country");if(s)s.value=st.country}else if(k==="plat")h.plat=h.plat===v?"":v;else if(k==="proj"){h.proj=h.proj===v?"":v;h.sel.proj=v}else if(k==="h"){h.drill=h.drill===v?null:v}render();return}});
document.addEventListener("change",e=>{const t=e.target;const h=st.hs;if(!h)return;
 if(t.dataset.hf){const k=t.dataset.hf,v=t.value;if(k==="country"){st.country=v;const s=document.getElementById("country");if(s)s.value=v}else if(k==="y")h.y=+v;else if(k==="m")h.m=+v;else{h[k]=v;if(k==="plat")h.biz=h.proj="";if(k==="biz")h.proj=""}render();return}
 if(t.matches("select[data-hsel]")){h.sel[t.dataset.hsel]=t.value;if(t.dataset.hsel==="proj")h.proj="";render();return}
 if(t.dataset.hdf==="kind"||t.dataset.hdf==="project"||t.dataset.hdf==="month"){hsForm()[t.dataset.hdf]=t.value;if(t.dataset.hdf!=="kind")hsPrefill();render()}});
// Pyramid rows carry "h:<key>" drill keys.
document.addEventListener("click",e=>{const t=e.target.closest("[data-drill^='h:']");if(!t||!st.hs)return;e.stopImmediatePropagation();const h=hsInit();const k=t.dataset.drill.slice(2);h.drill=h.drill===k?null:k;render()},true);

/* ---------- data entry ---------- */
function hsForm(){const h=hsInit();if(!h.form){const d=new Date();h.form={kind:"monthly",project:"",month:hsKey(d.getFullYear(),d.getMonth()+1),v:{}}}return h.form}
function hsPrefill(){const f=hsForm();if(f.kind!=="monthly")return;const r=(L.records||[]).find(x=>x.kind==="monthly"&&x.project===f.project&&x.data.month===f.month);f.v=r?{...r.data}:{};f.editId=r?r.id:null}
function hdata(){const g=liveGate();if(g)return g;const role=myRole();if(!["admin","hse","supervisor"].includes(role)&&!L.owner)return liveTag()+`<div class="panel"><h2>Only HSE staff enter HSSE data</h2></div>`;
 const h=hsInit();const f=hsForm();const P=myProjects();if(!f.project&&P[0]){f.project=P[0].id;hsPrefill()}const tab=h.dtab||"monthly";f.kind=tab;
 const inp=(k,l,type="number",extra="")=>`<div class="fld"><label for="hd-${k}">${l}</label><input id="hd-${k}" data-hv2="${k}" type="${type}" ${type==="number"?'min="0" step="any"':""} value="${esc(f.v[k]??"")}" ${extra}></div>`;
 const sel=(k,l,opts)=>`<div class="fld"><label for="hd-${k}">${l}</label><select id="hd-${k}" data-hv2="${k}">${opts.map(o=>`<option ${f.v[k]===o?"selected":""}>${esc(o)}</option>`).join("")}</select></div>`;
 const projSel=`<div class="fld"><label for="hd-p">Project</label><select id="hd-p" data-hdf="project">${P.map(p=>`<option value="${p.id}" ${p.id===f.project?"selected":""}>${esc(p.name)}</option>`).join("")}</select></div>`;
 let form="";
 if(tab==="monthly")form=`<div class="hd-row">${projSel}<div class="fld"><label for="hd-m">Month</label><input id="hd-m" type="month" data-hdf="month" value="${f.month}"></div></div>${f.editId?`<p class="hs-note">Figures already entered for this month are shown; saving updates them.</p>`:""}${MF.map(([sec,fs])=>`<h3>${sec}</h3><div class="hd-grid">${fs.map(([k,l])=>inp(k,l)).join("")}</div>`).join("")}`;
 if(tab==="finding")form=`<div class="hd-row">${projSel}${inp("date","Audit date","date")}</div><div class="hd-grid">${sel("audit","Audit",["Corporate","Process Safety","OSHE"])}${sel("element","Element",AUD_ELEMENTS)}${sel("ftype","Finding type",["Non-compliance","Observation","Opportunity for improvement"])}${sel("sev","Severity",["Major","Minor","Moderate","Significant","Observation","Best Practice"])}${inp("dueDate","Due date","date")}${sel("status","Status",["Open","Closed"])}</div>${inp("text","Finding","text")}`;
 if(tab==="audit")form=`<div class="hd-row">${projSel}${inp("date","Audit date","date")}</div><div class="hd-grid">${sel("audit","Audit",["OSHE","Corporate","Process Safety"])}${inp("score","Overall score (OSHE / corporate: %, process safety: 0–5)")}</div><h3>Process safety element scores (0–5, process safety audits only)</h3><div class="hd-grid">${PSM_ELEMENTS.map((e,i)=>inp("el"+i,e)).join("")}</div>`;
 if(tab==="grievance")form=`<div class="hd-row">${projSel}${inp("date","Date received","date")}</div><div class="hd-grid">${sel("category","Category",GRIEV_CATS)}${inp("epc","Contractor / company","text")}${sel("status","Status",["New","In progress","Closed"])}</div>${inp("text","Grievance (no names needed)","text")}`;
 if(tab==="accommodation")form=`<div class="hd-row">${projSel}${inp("date","Assessment date","date")}</div><div class="hd-grid">${inp("accommodations","Accommodations assessed")}${inp("camps","Camps")}${inp("workers","Workers housed")}${sel("managedBy","Managed by",["Contractor","Sub-contractor","Company","Third party"])}${inp("compliant","Checklist items compliant")}${inp("partial","Partially compliant")}${inp("nonCompliant","Non-compliant")}${inp("actions","Actions raised")}${inp("score","Site score (%)")}</div><h3>Non-compliant items by category</h3><div class="hd-grid">${ACC_CATS.map((c,i)=>inp("nc"+i,c)).join("")}</div><h3>Workers by nationality</h3><div class="hd-grid">${NATIONS.map((c,i)=>inp("na"+i,c)).join("")}</div>`;
 const recs=(L.records||[]).filter(r=>r.kind===tab).sort((a,b)=>b.ts-a.ts).slice(0,60);
 const desc=r=>tab==="monthly"?`${r.data.month} · ${hsN((+r.data.empHours||0)+(+r.data.conHours||0))} man-hours`:tab==="finding"?`${r.data.audit} · ${r.data.element} · ${r.data.sev}`:tab==="audit"?`${r.data.audit} · score ${r.data.score}`:tab==="grievance"?`${r.data.category} · ${r.data.epc||""}`:`Score ${r.data.score}% · ${hsN(r.data.workers)} workers`;
 const tabs=[["monthly","Monthly figures"],["finding","Audit findings"],["audit","Audit scores"],["grievance","Grievances"],["accommodation","Accommodation"]];
 return liveTag()+`<div class="ptabs" role="tablist">${tabs.map(([k,l])=>`<button role="tab" data-hdtab="${k}" aria-selected="${k===tab}">${l}</button>`).join("")}</div>
 <div class="grid2"><div class="panel"><h2>${tabs.find(t=>t[0]===tab)[1]}</h2>${P.length?form+`<button class="btn pri" id="hd-save" style="margin-top:12px">Save</button>`:`<p>No projects yet.</p>`}</div>
 <div class="panel"><h2>Recent entries <small>${recs.length}</small></h2>${recs.length?`<div class="tbl"><table><thead><tr><th>Project</th><th>Details</th><th>Status</th><th></th></tr></thead><tbody>${recs.map(r=>`<tr><td>${esc(projName(r.project))}</td><td>${esc(desc(r))}</td><td>${esc(r.data.status||"")}</td><td class="r">${["finding","grievance"].includes(tab)&&r.data.status!=="Closed"?`<button class="btn" data-hclose="${r.id}">Close</button>`:""}${myRole()==="admin"?`<button class="btn" data-hdel="${r.id}">Delete</button>`:""}</td></tr>`).join("")}</tbody></table></div>`:`<p style="color:var(--muted);margin:0">Nothing entered yet.</p>`}</div></div>`}
document.addEventListener("input",e=>{const t=e.target;if(t.dataset&&t.dataset.hv2&&st.hs){hsForm().v[t.dataset.hv2]=t.value}});
document.addEventListener("change",e=>{const t=e.target;if(t.dataset&&t.dataset.hv2&&st.hs){hsForm().v[t.dataset.hv2]=t.value}});
document.addEventListener("click",async e=>{const t=e.target.closest("#hd-save");if(!t)return;const h=hsInit(),f=hsForm(),tab=h.dtab||"monthly";const v={...f.v};
 document.querySelectorAll("[data-hv2]").forEach(x=>v[x.dataset.hv2]=x.value);const num=k=>v[k]===""||v[k]==null?undefined:+v[k];const dts=k=>v[k]?new Date(v[k]).getTime():Date.now();let data={},ts=Date.now();
 if(tab==="monthly"){const[y,m]=f.month.split("-").map(Number);ts=new Date(y,m-1,1).getTime();data={month:f.month};MFK.forEach(k=>{const n=num(k);if(n!==undefined)data[k]=n})}
 if(tab==="finding"){ts=dts("date");data={audit:v.audit||"Corporate",element:v.element||AUD_ELEMENTS[0],ftype:v.ftype||"Non-compliance",sev:v.sev||"Major",status:v.status||"Open",due:v.dueDate?new Date(v.dueDate).getTime():null,text:v.text||"",closedTs:v.status==="Closed"?Date.now():null}}
 if(tab==="audit"){ts=dts("date");const els={};PSM_ELEMENTS.forEach((e,i)=>{const n=num("el"+i);if(n!==undefined)els[e]=n});data={audit:v.audit||"OSHE",score:num("score")??0,elements:els};if(data.audit==="Process Safety"&&!num("score")&&Object.keys(els).length)data.score=+(Object.values(els).reduce((a,b)=>a+b,0)/Object.keys(els).length).toFixed(2)}
 if(tab==="grievance"){ts=dts("date");data={category:v.category||GRIEV_CATS[0],epc:v.epc||"",status:v.status||"New",text:v.text||"",closedTs:v.status==="Closed"?Date.now():null}}
 if(tab==="accommodation"){ts=dts("date");data={accommodations:num("accommodations")||0,camps:num("camps")||0,workers:num("workers")||0,managedBy:v.managedBy||"Contractor",compliant:num("compliant")||0,partial:num("partial")||0,nonCompliant:num("nonCompliant")||0,actions:num("actions")||0,score:num("score")||0,
  ncCats:Object.fromEntries(ACC_CATS.map((c,i)=>[c,num("nc"+i)||0]).filter(x=>x[1])),nations:Object.fromEntries(NATIONS.map((c,i)=>[c,num("na"+i)||0]).filter(x=>x[1]))}}
 const ok=await liveSave(async()=>{const c=L.db.collection("records");if(tab==="monthly"&&f.editId)await c.doc(f.editId).update({data,ts});else await c.add({project:f.project,kind:tab,ts,data,by:L.me.id})},"Saved");
 if(ok!==false){if(tab!=="monthly")f.v={};render()}});
async function hsDelete(id,btn){if(btn.dataset.sure!=="1"){btn.dataset.sure="1";btn.textContent="Tap again to delete";return}await liveSave(()=>L.db.collection("records").doc(id).delete(),"Deleted")}
async function hsCloseRec(id){const r=(L.records||[]).find(x=>x.id===id);if(!r)return;await liveSave(()=>L.db.collection("records").doc(id).update({data:{...r.data,status:"Closed",closedTs:Date.now()}}),"Closed")}

/* ---------- demo data for the HSSE dashboard ---------- */
function hsDemo(projects,R){const recs=[];const now=new Date();const y0=now.getFullYear()-1;const pick=a=>a[Math.floor(R()*a.length)];const ri=(a,b)=>Math.round(a+R()*(b-a));
 projects.forEach((p,pi)=>{const hc=p.headcount||200;const emp=Math.round(hc*(.12+R()*.15)),con=hc-emp;const nonC=(p.platform||"")==="Non-Construction";
  for(let y=y0;y<=now.getFullYear();y++)for(let m=1;m<=12;m++){if(y===now.getFullYear()&&m>now.getMonth()+1)break;const g=.9+R()*.25;const ts=new Date(y,m-1,1).getTime();
   const tp=Math.round(hc*1.6);recs.push({project:p.id,kind:"monthly",ts,data:{month:hsKey(y,m),empHead:Math.round(emp*g),conHead:Math.round(con*g),empHours:Math.round(emp*g*208),conHours:Math.round(con*g*240),trainings:ri(4,18),trainHours:Math.round(tp*(.7+R()*.6)),trainPlan:tp,attendees:Math.round(hc*(.4+R()*.5)),
    ptwIssued:ri(40,260),ptwReviewed:ri(30,200),ptwNC:ri(0,12),ccChecks:ri(60,300),ccAtRisk:ri(1,20),swa:ri(0,25),drills:ri(0,2),committee:1,incentives:ri(2,30),pfpiReviewed:ri(0,8),
    nhDisposed:ri(20,400),nhRecycled:ri(2,60),nhReused:ri(0,20),hzDisposed:ri(1,40),hzRecycled:ri(0,6),hzIncinerated:ri(0,4),faDisposed:nonC?ri(0,90):0,faRecycled:nonC?ri(0,30):0,diesel:ri(20,300),hfo:nonC?ri(0,200):0,lpg:ri(0,15),petrol:ri(2,30),gas:nonC?ri(0,500):0,chemical:ri(1,40),spill:ri(0,60),water:ri(400,4000)}})}
  const auds=["Corporate","OSHE"];for(let k=0;k<ri(4,14);k++){const ts=now.getTime()-ri(5,420)*864e5;const closed=R()<.85;recs.push({project:p.id,kind:"finding",ts,data:{audit:R()<.15&&nonC?"Process Safety":pick(auds),element:pick(AUD_ELEMENTS),ftype:pick(["Non-compliance","Observation","Observation","Opportunity for improvement"]),sev:pick(["Major","Minor","Minor","Moderate","Observation","Significant","Best Practice"]),status:closed?"Closed":"Open",due:ts+ri(14,60)*864e5,closedTs:closed?ts+ri(5,50)*864e5:null,text:""}})}
  recs.push({project:p.id,kind:"audit",ts:now.getTime()-ri(20,200)*864e5,data:{audit:"OSHE",score:ri(68,96),elements:{}}});
  if(nonC||R()<.5){const els=Object.fromEntries(PSM_ELEMENTS.map(e=>[e,+(2.6+R()*1.6).toFixed(2)]));recs.push({project:p.id,kind:"audit",ts:now.getTime()-ri(20,300)*864e5,data:{audit:"Process Safety",score:+(Object.values(els).reduce((a,b)=>a+b,0)/PSM_ELEMENTS.length).toFixed(2),elements:els}})}
  for(let k=0;k<ri(3,30);k++){const ts=now.getTime()-ri(1,300)*864e5;const s=R();const status=s<.65?"Closed":s<.85?"In progress":"New";recs.push({project:p.id,kind:"grievance",ts,data:{category:pick(GRIEV_CATS),epc:pick(["Main contractor","Civil sub-contractor","MEP sub-contractor","Manpower supplier","Transport supplier"]),status,closedTs:status==="Closed"?ts+ri(3,40)*864e5:null,text:""}})}
  const items=ri(120,420),nc=ri(2,30),pc=ri(2,25);const nat={};NATIONS.forEach(n=>{const v=ri(0,40);if(v)nat[n]=v});const ncc={};ACC_CATS.forEach(c=>{const v=ri(0,8);if(v)ncc[c]=v});
  recs.push({project:p.id,kind:"accommodation",ts:now.getTime()-ri(5,80)*864e5,data:{accommodations:ri(1,8),camps:ri(1,6),workers:Math.round(con*.7),managedBy:pick(["Contractor","Sub-contractor","Company","Third party"]),compliant:items-nc-pc,partial:pc,nonCompliant:nc,actions:nc+pc,score:Math.round((items-nc-pc*.5)/items*100),ncCats:ncc,ncItems:Object.fromEntries(["Fire equipment & muster point","Storage for belongings","Emergency contact charts","Pest control","HVAC & lighting","Laundry facilities","Bed spacing","Toilets cleaned frequently","Water quality checks","First aid room"].map(i=>[i,ri(0,6)]).filter(x=>x[1])),nations:nat}})});
 return recs}
function hsInjuryDemo(r,R){const pick=a=>a[Math.floor(R()*a.length)];if(!r.severity)return r;r.personType=R()<.8?"Contractor":"Employee";r.injuryType=pick(INJ_TYPES);r.bodyPart=pick(BODY_PARTS);r.incClass=r.severity==="Fatality"?"Class A":r.severity==="Lost Time"?"Class B":pick(["Class C","Class D","Class D"]);return r}
